screenPanels.initJs:
function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderRows(rows) {
    const tbody = container.querySelector('#orders-tbody');
    tbody.innerHTML = rows.map(r => {
      const priorityText = r.優先度 === 1 ? '高' : r.優先度 === 2 ? '中' : '低';
      const priorityColor = r.優先度 === 1 ? '#ff6a00' : r.優先度 === 2 ? '#ffa500' : '#666';
      const statusColor = r.ステータス === '完了' ? '#28a745' : r.ステータス === '進行中' ? '#007bff' : r.ステータス === '中止' ? '#dc3545' : '#6c757d';

      return `
        <tr data-id="${r.生産指示書ID || ''}">
          <td>${r.生産指示書番号 || ''}</td>
          <td>${r.製品名 || ''}</td>
          <td>${r.製造ライン名 || ''}</td>
          <td>${r.生産予定数量 || 0}</td>
          <td>${r.生産完了予定日時 ? new Date(r.生産完了予定日時).toLocaleDateString() : ''}</td>
          <td><span style="color: ${priorityColor}; font-weight: 500;">${priorityText}</span></td>
          <td><span style="color: ${statusColor}; font-weight: 500;">${r.ステータス || ''}</span></td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${r.生産指示書ID || ''}" style="font-size: 0.8rem; padding: 0.25rem 0.5rem;">編集</button>
            <button class="action-btn secondary delete-btn" data-id="${r.生産指示書ID || ''}" style="font-size: 0.8rem; padding: 0.25rem 0.5rem; margin-left: 0.25rem;">削除</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 2. 初期データを即座に描画
  renderRows(tables[0].records || []);

  // Chart.js初期化
  const monthlyCtx = container.querySelector('#monthly-chart').getContext('2d');
  const statusCtx = container.querySelector('#status-chart').getContext('2d');

  // 月別データ集計
  const monthlyData = {};
  (tables[0].records || []).forEach(r => {
    if (r.生産開始予定日時) {
      const month = r.生産開始予定日時.slice(0, 7);
      monthlyData[month] = (monthlyData[month] || 0) + 1;
    }
  });

  // ステータス別データ集計
  const statusData = {};
  (tables[0].records || []).forEach(r => {
    const status = r.ステータス || '未設定';
    statusData[status] = (statusData[status] || 0) + 1;
  });

  new window.Chart(monthlyCtx, {
    type: 'line',
    data: {
      labels: Object.keys(monthlyData).sort(),
      datasets: [{
        label: '生産指示書件数',
        data: Object.keys(monthlyData).sort().map(k => monthlyData[k]),
        borderColor: '#007bff',
        backgroundColor: 'rgba(0, 123, 255, 0.1)',
        tension: 0.4
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        y: { beginAtZero: true }
      }
    }
  });

  new window.Chart(statusCtx, {
    type: 'doughnut',
    data: {
      labels: Object.keys(statusData),
      datasets: [{
        data: Object.values(statusData),
        backgroundColor: ['#28a745', '#007bff', '#dc3545', '#6c757d', '#ffc107']
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false
    }
  });

  // 3. 検索ボタンのイベントリスナー
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const keyword = container.querySelector('#input-search').value.toLowerCase();
    const status = container.querySelector('#filter-status').value;

    const rows = await window.aivicApi.list(0);
    if (rows) {
      const filtered = rows.filter(r => {
        const matchKeyword = !keyword || 
          (r.生産指示書番号 && r.生産指示書番号.toLowerCase().includes(keyword)) ||
          (r.製品名 && r.製品名.toLowerCase().includes(keyword));
        const matchStatus = !status || r.ステータス === status;
        return matchKeyword && matchStatus;
      });
      renderRows(filtered);
    }
  });

  // 4. 登録ボタンのイベントリスナー
  container.querySelector('#create-form').addEventListener('submit', async (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    const data = {
      生産指示書ID: crypto.randomUUID(),
      生産指示書番号: formData.get('生産指示書番号'),
      製品ID: formData.get('製品ID'),
      製造ラインID: formData.get('製造ラインID'),
      生産予定数量: parseInt(formData.get('生産予定数量')),
      生産開始予定日時: formData.get('生産開始予定日時'),
      生産完了予定日時: formData.get('生産完了予定日時'),
      優先度: parseInt(formData.get('優先度')),
      ステータス: '未着手',
      備考: formData.get('備考'),
      作成者ID: 'current-user',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(0, data);
    if (saved) {
      e.target.reset();
      container.querySelector('input[name="優先度"][value="2"]').checked = true;
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
    }
  });

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#create-form').reset();
    container.querySelector('input[name="優先度"][value="2"]').checked = true;
  });

  // 5. 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const deleteBtn = e.target.closest('.delete-btn');
    if (deleteBtn) {
      if (!confirm('この生産指示書を削除しますか？')) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderRows(rows);
      return;
    }

    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      const id = editBtn.dataset.id;
      const rows = await window.aivicApi.list(0);
      if (rows) {
        const record = rows.find(r => r.生産指示書ID === id);
        if (record) {
          const form = container.querySelector('#create-form');
          form.querySelector('[name="生産指示書番号"]').value = record.生産指示書番号 || '';
          form.querySelector('[name="製品ID"]').value = record.製品ID || '';
          form.querySelector('[name="製造ラインID"]').value = record.製造ラインID || '';
          form.querySelector('[name="生産予定数量"]').value = record.生産予定数量 || '';
          form.querySelector('[name="生産開始予定日時"]').value = record.生産開始予定日時 || '';
          form.querySelector('[name="生産完了予定日時"]').value = record.生産完了予定日時 || '';
          form.querySelector(`[name="優先度"][value="${record.優先度}"]`).checked = true;
          form.querySelector('[name="備考"]').value = record.備考 || '';

          // 編集モードに切り替え
          form.dataset.editId = id;
          container.querySelector('[data-testid="save-button"]').textContent = '更新';
        }
      }
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-csv-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const headers = ['生産指示書番号', '製品名', '製造ライン名', '生産予定数量', '生産完了予定日時', '優先度', 'ステータス', '備考'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...rows.map(r => [
          r.生産指示書番号 || '',
          r.製品名 || '',
          r.製造ライン名 || '',
          r.生産予定数量 || '',
          r.生産完了予定日時 || '',
          r.優先度 === 1 ? '高' : r.優先度 === 2 ? '中' : '低',
          r.ステータス || '',
          r.備考 || ''
        ].map(field => `"${field}"`).join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = '生産指示書一覧.csv';
      a.click();
      URL.revokeObjectURL(url);
    }
  });

  // 画面遷移ボタン
  container.querySelector('#btn-delivery').addEventListener('click', () => {
    window.showScreen("scr-1780995244814");
  });

  container.querySelector('#btn-results').addEventListener('click', () => {
    window.showScreen("scr-1780995265664");
  });

  // フォーム送信時の編集/新規判定
  const originalSubmitHandler = container.querySelector('#create-form').onsubmit;
  container.querySelector('#create-form').addEventListener('submit', async (e) => {
    e.preventDefault();
    const form = e.target;
    const editId = form.dataset.editId;

    if (editId) {
      // 編集モード
      const formData = new FormData(form);
      const data = {
        生産指示書番号: formData.get('生産指示書番号'),
        製品ID: formData.get('製品ID'),
        製造ラインID: formData.get('製造ラインID'),
        生産予定数量: parseInt(formData.get('生産予定数量')),
        生産開始予定日時: formData.get('生産開始予定日時'),
        生産完了予定日時: formData.get('生産完了予定日時'),
        優先度: parseInt(formData.get('優先度')),
        備考: formData.get('備考'),
        更新日時: new Date().toISOString()
      };

      const updated = await window.aivicApi.update(0, editId, data);
      if (updated) {
        form.reset();
        delete form.dataset.editId;
        container.querySelector('[data-testid="save-button"]').textContent = '作成';
        container.querySelector('input[name="優先度"][value="2"]').checked = true;
        const rows = await window.aivicApi.list(0);
        if (rows) renderRows(rows);
      }
    }
  });
}

function(container, apiUrl, tables) {
  // 作業実績テーブルのインデックスを特定
  const workResultTableIndex = tables.findIndex(t => t.tableName === '作業実績');
  const handoverTableIndex = tables.findIndex(t => t.tableName === '工程引き継ぎ情報');

  // 生産指示書選択時の製品名・工程名表示更新
  const productionOrderSelect = container.querySelector('select[name="productionOrderId"]');
  const productNameDisplay = container.querySelector('[data-testid="product-name-display"]');
  const processNameDisplay = container.querySelector('[data-testid="process-name-display"]');

  productionOrderSelect.addEventListener('change', function() {
    const selectedValue = this.value;
    if (selectedValue === 'po-001') {
      productNameDisplay.value = 'エンジン部品A';
      processNameDisplay.value = '切削加工';
    } else if (selectedValue === 'po-002') {
      productNameDisplay.value = 'フレーム組立B';
      processNameDisplay.value = '溶接工程';
    } else if (selectedValue === 'po-003') {
      productNameDisplay.value = '配線ハーネス';
      processNameDisplay.value = '組立工程';
    } else if (selectedValue === 'po-004') {
      productNameDisplay.value = '制御基板';
      processNameDisplay.value = '実装工程';
    } else {
      productNameDisplay.value = '';
      processNameDisplay.value = '';
    }
  });

  // 作業実績登録ボタンのイベントリスナー
  container.querySelector('#btn-save-work-result').addEventListener('click', async function() {
    const form = container.querySelector('#work-result-form');
    const formData = new FormData(form);

    const workResultData = {
      生産指示書ID: formData.get('productionOrderId'),
      作業者ID: formData.get('workerName'),
      作業開始日時: formData.get('startTime'),
      作業終了日時: formData.get('endTime'),
      実績数量: parseInt(formData.get('actualQuantity')) || 0,
      良品数量: parseInt(formData.get('goodQuantity')) || 0,
      不良品数量: parseInt(formData.get('defectQuantity')) || 0,
      作業状況: '完了',
      備考: formData.get('defectReason') ? `不良理由: ${formData.get('defectReason')}` : '',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    if (workResultTableIndex >= 0) {
      const saved = await window.aivicApi.save(workResultTableIndex, workResultData);
      if (saved) {
        alert('作業実績を登録しました');
        form.reset();
        productNameDisplay.value = '';
        processNameDisplay.value = '';
      }
    } else {
      alert('作業実績テーブルが見つかりません');
    }
  });

  // 引き継ぎ情報登録ボタンのイベントリスナー
  container.querySelector('#btn-save-handover').addEventListener('click', async function() {
    const form = container.querySelector('#handover-form');
    const formData = new FormData(form);

    const handoverData = {
      生産指示書ID: container.querySelector('select[name="productionOrderId"]').value,
      引き継ぎ先工程ID: formData.get('nextProcessId'),
      引き継ぎ数量: parseInt(formData.get('handoverQuantity')) || 0,
      ロット番号: formData.get('lotNumber'),
      品質状況: formData.get('qualityStatus'),
      注意事項: formData.get('notes'),
      引き継ぎ日時: new Date().toISOString(),
      引き継ぎ状態: '引き継ぎ済み',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    if (handoverTableIndex >= 0) {
      const saved = await window.aivicApi.save(handoverTableIndex, handoverData);
      if (saved) {
        alert('引き継ぎ情報を登録しました');
        form.reset();
        // 引き継ぎ履歴を再読み込み
        loadHandoverHistory();
      }
    } else {
      alert('工程引き継ぎ情報テーブルが見つかりません');
    }
  });

  // 引き継ぎ履歴の再描画関数
  function renderHandoverHistory(rows) {
    const tbody = container.querySelector('#handover-history-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="text-align: center; color: var(--text-muted);">引き継ぎ履歴がありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(row => {
      const qualityBadge = getQualityBadge(row.品質状況 || '');
      const statusBadge = getStatusBadge(row.引き継ぎ状態 || '');

      return `
        <tr>
          <td>${formatDateTime(row.引き継ぎ日時)}</td>
          <td>${row.引き継ぎ先工程名 || '-'}</td>
          <td>${row.引き継ぎ数量 || 0}個</td>
          <td>${qualityBadge}</td>
          <td>${statusBadge}</td>
        </tr>
      `;
    }).join('');
  }

  // 品質状況バッジ
  function getQualityBadge(status) {
    const badges = {
      '良好': '<span style="background: rgba(34,197,94,0.2); color: #22c55e; padding: 0.2rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">良好</span>',
      '注意': '<span style="background: rgba(251,191,36,0.2); color: #fbbf24; padding: 0.2rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">注意</span>',
      '要確認': '<span style="background: rgba(249,115,22,0.2); color: #f97316; padding: 0.2rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">要確認</span>',
      '不良': '<span style="background: rgba(239,68,68,0.2); color: #ef4444; padding: 0.2rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">不良</span>'
    };
    return badges[status] || status;
  }

  // 状態バッジ
  function getStatusBadge(status) {
    const badges = {
      '引き継ぎ済み': '<span style="background: rgba(251,191,36,0.2); color: #fbbf24; padding: 0.2rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">引き継ぎ済み</span>',
      '受け取り済み': '<span style="background: rgba(59,130,246,0.2); color: #3b82f6; padding: 0.2rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">受け取り済み</span>',
      '完了': '<span style="background: rgba(34,197,94,0.2); color: #22c55e; padding: 0.2rem 0.5rem; border-radius: 12px; font-size: 0.8rem;">完了</span>'
    };
    return badges[status] || status;
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // 引き継ぎ履歴読み込み
  async function loadHandoverHistory() {
    if (handoverTableIndex >= 0) {
      const rows = await window.aivicApi.list(handoverTableIndex);
      if (rows) {
        renderHandoverHistory(rows);
      }
    }
  }

  // 初期データ読み込み
  if (handoverTableIndex >= 0) {
    renderHandoverHistory(tables[handoverTableIndex].records || []);
  }
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const PRODUCTION_ORDERS_TABLE = 3; // 生産指示書
  const ALERTS_TABLE = 12; // アラート通知
  const ANOMALY_LOGS_TABLE = 13; // 異常値検出ログ
  const QUALITY_RESULTS_TABLE = 7; // 品質検査結果
  const PROGRESS_TABLE = 11; // 進捗管理

  let selectedAlertId = null;

  // 生産指示書テーブル再描画
  function renderProductionOrders(orders) {
    const tbody = container.querySelector('#production-orders-tbody');
    tbody.innerHTML = orders.map(order => {
      const progressPercent = Math.round((order.生産実績数量 || 0) / (order.生産予定数量 || 1) * 100);
      const statusColor = order.ステータス === '完了' ? '#22c55e' : 
                         order.ステータス === '進行中' ? '#f59e0b' : '#6b7280';

      return `
        <tr data-id="${order.id}">
          <td>${order.生産指示書番号 || ''}</td>
          <td>${order.製品名 || ''}</td>
          <td>${order.製造ライン名 || ''}</td>
          <td>
            <div style="display: flex; align-items: center; gap: 0.5rem;">
              <div style="flex: 1; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px;">
                <div style="width: ${progressPercent}%; height: 100%; background: var(--primary); border-radius: 3px;"></div>
              </div>
              <span style="font-size: 0.8rem; color: var(--text);">${progressPercent}%</span>
            </div>
          </td>
          <td><span style="padding: 0.2rem 0.5rem; background: ${statusColor}; color: #fff; border-radius: 3px; font-size: 0.75rem;">${order.ステータス || ''}</span></td>
          <td>${order.生産完了予定日時 ? new Date(order.生産完了予定日時).toLocaleDateString() : ''}</td>
          <td>
            <button class="action-btn secondary view-detail-btn" data-id="${order.id}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // アラート通知テーブル再描画
  function renderAlerts(alerts) {
    const tbody = container.querySelector('#alerts-tbody');
    tbody.innerHTML = alerts.map(alert => {
      const levelColor = alert.重要度 === '緊急' ? '#ef4444' :
                        alert.重要度 === '高' ? '#f59e0b' :
                        alert.重要度 === '中' ? '#3b82f6' : '#6b7280';
      const statusColor = alert.通知ステータス === '完了' ? '#22c55e' :
                         alert.通知ステータス === '対応中' ? '#f59e0b' : '#6b7280';

      return `
        <tr data-id="${alert.id}">
          <td><span style="padding: 0.2rem 0.5rem; background: ${levelColor}; color: #fff; border-radius: 3px; font-size: 0.75rem;">${alert.重要度 || ''}</span></td>
          <td>${alert.タイトル || ''}</td>
          <td>${alert.作成日時 ? new Date(alert.作成日時).toLocaleString() : ''}</td>
          <td><span style="padding: 0.2rem 0.5rem; background: ${statusColor}; color: #fff; border-radius: 3px; font-size: 0.75rem;">${alert.通知ステータス || ''}</span></td>
          <td>
            ${alert.通知ステータス !== '完了' ? `<button class="action-btn secondary respond-alert-btn" data-id="${alert.id}">対応</button>` : ''}
          </td>
        </tr>
      `;
    }).join('');
  }

  // 異常値検出ログテーブル再描画
  function renderAnomalyLogs(logs) {
    const tbody = container.querySelector('#anomaly-logs-tbody');
    tbody.innerHTML = logs.map(log => {
      const levelColor = log.異常レベル === '重大' ? '#ef4444' :
                        log.異常レベル === '注意' ? '#f59e0b' : '#6b7280';
      const statusColor = log.対応状況 === '完了' ? '#22c55e' :
                         log.対応状況 === '対応中' ? '#f59e0b' : '#6b7280';

      return `
        <tr data-id="${log.id}">
          <td>${log.検出項目名 || ''}</td>
          <td>${log.検出値 || ''}</td>
          <td><span style="padding: 0.2rem 0.5rem; background: ${levelColor}; color: #fff; border-radius: 3px; font-size: 0.75rem;">${log.異常レベル || ''}</span></td>
          <td>${log.検出日時 ? new Date(log.検出日時).toLocaleString() : ''}</td>
          <td><span style="padding: 0.2rem 0.5rem; background: ${statusColor}; color: #fff; border-radius: 3px; font-size: 0.75rem;">${log.対応状況 || ''}</span></td>
        </tr>
      `;
    }).join('');
  }

  // 工程別進捗チャート描画
  function drawProgressChart() {
    const canvas = container.querySelector('#progress-chart');
    const ctx = canvas.getContext('2d');

    // Canvas サイズ設定
    canvas.width = 600;
    canvas.height = 300;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ
    const processes = ['加工', '組立', '検査', '梱包'];
    const progressData = [85, 72, 94, 68];

    const barWidth = 80;
    const barSpacing = 120;
    const startX = 60;
    const maxHeight = 200;

    // バー描画
    processes.forEach((process, index) => {
      const x = startX + index * barSpacing;
      const height = (progressData[index] / 100) * maxHeight;
      const y = canvas.height - 60 - height;

      // バー
      ctx.fillStyle = '#3b82f6';
      ctx.fillRect(x, y, barWidth, height);

      // 工程名
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(process, x + barWidth / 2, canvas.height - 20);

      // 進捗率
      ctx.fillStyle = '#d0e4ff';
      ctx.font = '14px sans-serif';
      ctx.fillText(`${progressData[index]}%`, x + barWidth / 2, y - 10);
    });

    // Y軸ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'right';
    for (let i = 0; i <= 100; i += 20) {
      const y = canvas.height - 60 - (i / 100) * maxHeight;
      ctx.fillText(`${i}%`, 50, y + 4);
    }
  }

  // データ読み込みと初期表示
  async function loadData() {
    try {
      const [orders, alerts, logs] = await Promise.all([
        window.aivicApi.list(PRODUCTION_ORDERS_TABLE),
        window.aivicApi.list(ALERTS_TABLE),
        window.aivicApi.list(ANOMALY_LOGS_TABLE)
      ]);

      renderProductionOrders(orders || []);
      renderAlerts(alerts || []);
      renderAnomalyLogs(logs || []);

      // KPI更新
      const activeLines = orders ? orders.filter(o => o.ステータス === '進行中').length : 0;
      const totalProduction = orders ? orders.reduce((sum, o) => sum + (o.生産実績数量 || 0), 0) : 0;
      const pendingAlerts = alerts ? alerts.filter(a => a.通知ステータス !== '完了').length : 0;
      const avgProgress = orders && orders.length > 0 ? 
        Math.round(orders.reduce((sum, o) => sum + ((o.生産実績数量 || 0) / (o.生産予定数量 || 1) * 100), 0) / orders.length) : 0;

      container.querySelector('#active-lines').textContent = `${activeLines}/4`;
      container.querySelector('#daily-production').textContent = `${totalProduction.toLocaleString()}個`;
      container.querySelector('#pending-alerts').textContent = `${pendingAlerts}件`;
      container.querySelector('#avg-progress').textContent = `${avgProgress}%`;

    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 初期データ表示
  renderProductionOrders(tables[PRODUCTION_ORDERS_TABLE]?.records || []);
  renderAlerts(tables[ALERTS_TABLE]?.records || []);
  renderAnomalyLogs(tables[ANOMALY_LOGS_TABLE]?.records || []);
  drawProgressChart();

  // データ読み込み
  loadData();

  // 更新ボタン
  container.querySelector('#btn-refresh').addEventListener('click', loadData);

  // フィルタリング
  function applyFilters() {
    const lineFilter = container.querySelector('#line-select').value;
    const dateFrom = container.querySelector('#date-from').value;
    const dateTo = container.querySelector('#date-to').value;
    const alertLevelFilter = container.querySelector('#alert-level-filter').value;

    loadData(); // 簡易実装：フィルタ条件は将来的にAPI側で処理
  }

  container.querySelector('#line-select').addEventListener('change', applyFilters);
  container.querySelector('#date-from').addEventListener('change', applyFilters);
  container.querySelector('#date-to').addEventListener('change', applyFilters);
  container.querySelector('#alert-level-filter').addEventListener('change', applyFilters);

  // アラート対応モーダル
  const alertModal = container.querySelector('#alert-modal');

  container.addEventListener('click', async (e) => {
    // アラート対応ボタン
    const respondBtn = e.target.closest('.respond-alert-btn');
    if (respondBtn) {
      selectedAlertId = respondBtn.dataset.id;
      alertModal.style.display = 'block';
      return;
    }

    // 詳細表示ボタン
    const detailBtn = e.target.closest('.view-detail-btn');
    if (detailBtn) {
      // 詳細画面への遷移は将来実装
      console.log('詳細表示:', detailBtn.dataset.id);
      return;
    }
  });

  // モーダル操作
  container.querySelector('#btn-cancel-response').addEventListener('click', () => {
    alertModal.style.display = 'none';
    selectedAlertId = null;
    container.querySelector('#response-comment').value = '';
  });

  container.querySelector('#btn-complete-response').addEventListener('click', async () => {
    if (!selectedAlertId) return;

    const comment = container.querySelector('#response-comment').value;

    try {
      await window.aivicApi.update(ALERTS_TABLE, selectedAlertId, {
        通知ステータス: '完了',
        対応完了フラグ: true,
        対応完了日時: new Date().toISOString(),
        対応コメント: comment
      });

      alertModal.style.display = 'none';
      selectedAlertId = null;
      container.querySelector('#response-comment').value = '';

      // データ再読み込み
      loadData();

    } catch (error) {
      console.error('アラート対応エラー:', error);
    }
  });

  // モーダル外クリックで閉じる
  alertModal.addEventListener('click', (e) => {
    if (e.target === alertModal) {
      alertModal.style.display = 'none';
      selectedAlertId = null;
      container.querySelector('#response-comment').value = '';
    }
  });
}

