  // 品質検査結果グラフの描画
  function drawQualityChart(data) {
    const canvas = container.querySelector('#quality-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // グラフの基本設定
    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // サンプルデータでの折れ線グラフ
    const sampleData = [85, 82, 88, 75, 90, 78, 85];
    const stepX = chartWidth / (sampleData.length - 1);

    ctx.strokeStyle = '#00aa44';
    ctx.lineWidth = 2;
    ctx.beginPath();

    sampleData.forEach((value, index) => {
      const x = padding + index * stepX;
      const y = canvas.height - padding - (value / 100) * chartHeight;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // データポイント
    ctx.fillStyle = '#00aa44';
    sampleData.forEach((value, index) => {
      const x = padding + index * stepX;
      const y = canvas.height - padding - (value / 100) * chartHeight;
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  // 作業実績比較チャートの描画
  function drawPerformanceChart() {
    const canvas = container.querySelector('#performance-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const padding = 40;
    const barWidth = 30;
    const data = [
      { label: '計画', value: 100, color: '#0088cc' },
      { label: '実績', value: 85, color: '#00aa44' },
      { label: '不良', value: 15, color: '#ff6a00' }
    ];

    data.forEach((item, index) => {
      const x = padding + index * (barWidth + 20);
      const barHeight = (item.value / 120) * (canvas.height - padding * 2);
      const y = canvas.height - padding - barHeight;

      ctx.fillStyle = item.color;
      ctx.fillRect(x, y, barWidth, barHeight);

      // ラベル
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(item.label, x + barWidth / 2, canvas.height - padding + 15);
      ctx.fillText(item.value, x + barWidth / 2, y - 5);
    });
  }

  // 原因分析ツリーの更新
