      // サンプル検査項目を追加（品質基準にデータがない場合）
      if (inspectionItems.length === 0) {
        inspectionItems = [
          { 検査項目名: '寸法精度', 基準値: '±0.1', 単位: 'mm', 実測値: '', 判定結果: '', 備考: '' },
          { 検査項目名: '表面粗さ', 基準値: 'Ra1.6以下', 単位: 'μm', 実測値: '', 判定結果: '', 備考: '' },
          { 検査項目名: '硬度', 基準値: 'HRC58-62', 単位: 'HRC', 実測値: '', 判定結果: '', 備考: '' },
          { 検査項目名: '外観検査', 基準値: '傷・打痕なし', 単位: '-', 実測値: '', 判定結果: '', 備考: '' }
        ];
      }

      renderInspectionItems(inspectionItems);

    } catch (error) {
      console.error('検査項目読み込みエラー:', error);
      alert('検査項目の読み込みに失敗しました');
    }
  });

  // 測定値・判定結果の変更を監視
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('measured-value')) {
      const index = parseInt(e.target.dataset.index);
      inspectionItems[index].実測値 = e.target.value;
    } else if (e.target.classList.contains('judgment-result')) {
      const index = parseInt(e.target.dataset.index);
      inspectionItems[index].判定結果 = e.target.value;
    } else if (e.target.classList.contains('item-notes')) {
      const index = parseInt(e.target.dataset.index);
      inspectionItems[index].備考 = e.target.value;
    }
  });

  // 下書き保存
  container.querySelector('#btn-save-draft').addEventListener('click', async () => {
    if (!currentProductionOrder || inspectionItems.length === 0) {
      alert('検査対象と検査項目を設定してください');
      return;
    }

    try {
      const inspectionData = {
        生産指示書ID: currentProductionOrder.生産指示書ID,
        製品ID: currentProductionOrder.製品ID,
        工程ID: container.querySelector('#process-select').value,
        検査員名: container.querySelector('#inspector-name').value,
        検査日時: container.querySelector('#inspection-datetime').value,
        検査機器: container.querySelector('#inspection-equipment').value,
        不良内容: container.querySelector('#defect-notes').value,
        検査状態: '下書き',
        検査項目: JSON.stringify(inspectionItems)
      };

      // 一時保存用にローカルストレージに保存
      localStorage.setItem('inspection_draft', JSON.stringify(inspectionData));
      alert('下書きを保存しました');

    } catch (error) {
      console.error('下書き保存エラー:', error);
      alert('下書きの保存に失敗しました');
    }
  });

  // 検査結果登録
  container.querySelector('#btn-register').addEventListener('click', async () => {
    if (!currentProductionOrder || inspectionItems.length === 0) {
      alert('検査対象と検査項目を設定してください');
      return;
    }

    const inspectorName = container.querySelector('#inspector-name').value.trim();
    const inspectionDatetime = container.querySelector('#inspection-datetime').value;

    if (!inspectorName || !inspectionDatetime) {
      alert('検査員名と検査日時を入力してください');
      return;
    }

    // 全項目の判定結果チェック
    const incompleteItems = inspectionItems.filter(item => !item.判定結果);
    if (incompleteItems.length > 0) {
      if (!confirm(`${incompleteItems.length}件の項目で判定結果が未入力です。このまま登録しますか？`)) {
        return;
      }
    }

    try {
      // 各検査項目を個別に登録
      for (const item of inspectionItems) {
        const resultData = {
          生産指示書ID: currentProductionOrder.生産指示書ID,
          製品ID: currentProductionOrder.製品ID,
          工程ID: container.querySelector('#process-select').value,
          検査項目名: item.検査項目名,
          検査基準値: item.基準値,
          実測値: item.実測値,
          判定結果: item.判定結果 || '未判定',
          検査数量: 1,
          不良数量: item.判定結果 === '不合格' ? 1 : 0,
          検査日時: inspectionDatetime,
          検査者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
          備考: item.備考 || container.querySelector('#defect-notes').value
        };

        await window.aivicApi.save(8, resultData); // 品質検査結果テーブル
      }

      alert('検査結果を登録しました');

      // フォームをリセット
      container.querySelector('#production-order-input').value = '';
      container.querySelector('#order-info').style.display = 'none';
      container.querySelector('#inspector-name').value = '';
      container.querySelector('#defect-notes').value = '';
      container.querySelector('#process-select').value = '';
      currentProductionOrder = null;
      inspectionItems = [];
      renderInspectionItems([]);

      // 下書きを削除
      localStorage.removeItem('inspection_draft');

    } catch (error) {
      console.error('検査結果登録エラー:', error);
      alert('検査結果の登録に失敗しました');
    }
  });

  // 下書きデータの復元
  const draftData = localStorage.getItem('inspection_draft');
  if (draftData) {
    try {
      const draft = JSON.parse(draftData);
      if (confirm('保存された下書きがあります。復元しますか？')) {
        container.querySelector('#inspector-name').value = draft.検査員名 || '';
        container.querySelector('#inspection-datetime').value = draft.検査日時 || '';
        container.querySelector('#inspection-equipment').value = draft.検査機器 || '';
        container.querySelector('#defect-notes').value = draft.不良内容 || '';

        if (draft.検査項目) {
          inspectionItems = JSON.parse(draft.検査項目);
          renderInspectionItems(inspectionItems);
        }
      }
    } catch (error) {
      console.error('下書き復元エラー:', error);
    }
  }

  // 初期表示
  renderInspectionItems([]);
}

function(container, apiUrl, tables) {
  let selectedProductId = null;

  // 1. 再描画関数の定義
  function renderProducts(products) {
    const tbody = container.querySelector("#product-tbody");
    tbody.innerHTML = products.map(p => `
      <tr data-id="${p.id}" style="cursor: pointer; border-bottom: 1px solid var(--border);" class="product-row">
        <td style="padding: 0.5rem; color: var(--text);">${p.製品コード || ""}</td>
        <td style="padding: 0.5rem; color: var(--text);">${p.製品名 || ""}</td>
