        <td style="padding: 0.5rem; color: var(--text);">${p.規格 || ""}</td>
        <td style="padding: 0.5rem; color: var(--text);">${p.単位 || ""}</td>
      </tr>
    `).join("");
  }

  function renderProcesses(processes) {
    const tbody = container.querySelector("#process-tbody");
    tbody.innerHTML = processes.map(p => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 0.5rem; color: var(--text);">${p.工程コード || ""}</td>
