  function renderMaterials(materials) {
    const tbody = container.querySelector("#material-tbody");
    tbody.innerHTML = materials.map(m => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 0.5rem; color: var(--text);">${m.ライン名 || ""}</td>
        <td style="padding: 0.5rem; color: var(--text);">
          <span style="padding: 0.2rem 0.5rem; border-radius: 12px; font-size: 0.8rem; background: ${m.ライン状態 === '稼働中' ? 'rgba(34, 197, 94, 0.2)' : 'rgba(239, 68, 68, 0.2)'}; color: ${m.ライン状態 === '稼働中' ? '#22c55e' : '#ef4444'};">
