  function renderQuality(qualities) {
    const tbody = container.querySelector("#quality-tbody");
    tbody.innerHTML = qualities.map(q => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 0.5rem; color: var(--text);">${q.基準名 || ""}</td>
        <td style="padding: 0.5rem; color: var(--text);">${q.検査項目名 || ""}</td>
        <td style="padding: 0.5rem; color: var(--text);">${q.基準値 || ""}</td>
        <td style="padding: 0.5rem; color: var(--text);">${q.上限値 || ""}</td>
        <td style="padding: 0.5rem; color: var(--text);">${q.下限値 || ""}</td>
        <td style="padding: 0.5rem; color: var(--text);">${q.単位 || ""}</td>
      </tr>
    `).join("");
  }

  function showProductDetail(product) {
    selectedProductId = product.id;

    // 基本情報を表示
    container.querySelector("#spec-product-code").textContent = product.製品コード || "-";
    container.querySelector("#spec-product-name").textContent = product.製品名 || "-";
    container.querySelector("#spec-standard").textContent = product.規格 || "-";
    container.querySelector("#spec-cost").textContent = product.標準原価 ? `¥${product.標準原価.toLocaleString()}` : "-";
    container.querySelector("#spec-leadtime").textContent = product.標準リードタイム ? `${product.標準リードタイム}日` : "-";
    container.querySelector("#spec-unit").textContent = product.単位 || "-";

    // タブを表示
    container.querySelector("#detail-content").style.display = "none";
    container.querySelector("#detail-tabs").style.display = "block";

    // 関連データを読み込み
    loadRelatedData(product.id);
  }

  async function loadRelatedData(productId) {
    try {
      // 工程情報を読み込み
      const processes = await window.aivicApi.list(2);
      renderProcesses(processes || []);

      // 製造ライン情報を読み込み
      const lines = await window.aivicApi.list(3);
      const productLines = lines ? lines.filter(l => l.製品_ID === productId) : [];
      renderMaterials(productLines);

      // 品質基準を読み込み
      const qualities = await window.aivicApi.list(11);
      const productQualities = qualities ? qualities.filter(q => q.製品ID === productId) : [];
      renderQuality(productQualities);
    } catch (error) {
      console.error("関連データの読み込みに失敗しました:", error);
    }
  }

  // 2. 初期データを即座に描画
  renderProducts(tables[0].records || []);

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const code = container.querySelector("#product-code").value.trim();
    const name = container.querySelector("#product-name").value.trim();
    const category = container.querySelector("#product-category").value;

    try {
      const products = await window.aivicApi.list(0);
      const filtered = products.filter(p => {
        const matchCode = !code || (p.製品コード && p.製品コード.includes(code));
        const matchName = !name || (p.製品名 && p.製品名.includes(name));
        const matchCategory = !category || p.製品分類 === category;
        return matchCode && matchName && matchCategory;
      });
      renderProducts(filtered);
    } catch (error) {
      console.error("検索に失敗しました:", error);
    }
  });

  // クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#product-code").value = "";
    container.querySelector("#product-name").value = "";
    container.querySelector("#product-category").value = "";
    renderProducts(tables[0].records || []);
  });

  // CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    try {
      const products = await window.aivicApi.list(0);
      const headers = ["製品コード", "製品名", "製品分類", "規格", "単位", "標準原価", "標準リードタイム"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...products.map(p => [
          p.製品コード || "",
          p.製品名 || "",
          p.製品分類 || "",
          p.規格 || "",
          p.単位 || "",
          p.標準原価 || "",
          p.標準リードタイム || ""
        ].map(field => `"${field}"`).join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "製品一覧.csv";
      link.click();
    } catch (error) {
      console.error("CSVエクスポートに失敗しました:", error);
    }
  });

  // 戻るボタン
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1780995230897");
  });

  // 4. 行クリックで詳細表示
  container.addEventListener("click", (e) => {
    const row = e.target.closest(".product-row");
    if (row) {
      const productId = row.dataset.id;
      const products = tables[0].records || [];
      const product = products.find(p => p.id === productId);
      if (product) {
        showProductDetail(product);
      }
    }
  });

  // タブ切り替え
  container.addEventListener("click", (e) => {
    const tabBtn = e.target.closest(".tab-btn");
    if (tabBtn) {
      const tabName = tabBtn.dataset.tab;

      // タブボタンの状態を更新
      container.querySelectorAll(".tab-btn").forEach(btn => {
        btn.classList.remove("active");
        btn.style.color = "var(--text-muted)";
        btn.style.borderBottomColor = "transparent";
      });
      tabBtn.classList.add("active");
      tabBtn.style.color = "var(--text)";
      tabBtn.style.borderBottomColor = "var(--primary)";

      // タブコンテンツの表示を切り替え
      container.querySelectorAll(".tab-content").forEach(content => {
        content.style.display = "none";
      });
      container.querySelector(`#tab-${tabName}`).style.display = "block";
    }
  });
}

function(container, apiUrl, tables) {
  // 現在の日時を設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#delivery-datetime').value = now.toISOString().slice(0, 16);

  // 再描画関数の定義
  function renderDeliveryHistory(rows) {
    const tbody = container.querySelector('#delivery-tbody');
    const totalCount = container.querySelector('#total-count');
    const displayCount = container.querySelector('#display-count');

    totalCount.textContent = rows.length;
    displayCount.textContent = rows.length;

    tbody.innerHTML = rows.map(row => {
      const statusBadge = getStatusBadge(row.配信ステータス || 'pending');
      const priorityText = getPriorityText(row.優先度 || 2);

      return `
        <tr data-id="${row.id || ''}">
          <td>${formatDateTime(row.配信日時 || row.作成日時)}</td>
          <td>${row.生産指示書番号 || ''}</td>
          <td>${row.製品名 || ''}</td>
          <td>${row.ライン名 || ''}</td>
          <td>${row.作業者名 || ''}</td>
          <td>${priorityText}</td>
          <td>${statusBadge}</td>
          <td>
            <button class="action-btn secondary resend-btn" data-id="${row.id || ''}" style="font-size: 0.75rem; padding: 0.25rem 0.5rem;">再送</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  function getStatusBadge(status) {
    const badges = {
      'pending': '<span style="background: #ffc107; color: #000; padding: 0.125rem 0.5rem; border-radius: 12px; font-size: 0.75rem;">配信中</span>',
      'delivered': '<span style="background: #28a745; color: #fff; padding: 0.125rem 0.5rem; border-radius: 12px; font-size: 0.75rem;">配信完了</span>',
      'failed': '<span style="background: #dc3545; color: #fff; padding: 0.125rem 0.5rem; border-radius: 12px; font-size: 0.75rem;">配信失敗</span>',
      'read': '<span style="background: #17a2b8; color: #fff; padding: 0.125rem 0.5rem; border-radius: 12px; font-size: 0.75rem;">既読</span>'
    };
    return badges[status] || badges['pending'];
  }

  function getPriorityText(priority) {
    const priorities = { 1: '高', 2: '中', 3: '低' };
    return priorities[priority] || '中';
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', { 
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit'
    });
  }

  // 初期データの読み込みと表示
  window.aivicApi.list(0).then(rows => {
    if (rows) {
      // サンプルデータを追加
      const sampleData = [
        {
          id: 'sample1',
          配信日時: '2024-01-15T09:30:00',
          生産指示書番号: 'PRD-2024-001',
          製品名: 'エンジン部品A',
          ライン名: 'ライン1',
          作業者名: '田中 太郎',
          優先度: 1,
          配信ステータス: 'delivered'
        },
        {
          id: 'sample2',
          配信日時: '2024-01-15T10:15:00',
          生産指示書番号: 'PRD-2024-002',
          製品名: '制御基板B',
          ライン名: 'ライン2',
          作業者名: '佐藤 花子',
          優先度: 2,
          配信ステータス: 'read'
        },
        {
          id: 'sample3',
          配信日時: '2024-01-15T11:00:00',
          生産指示書番号: 'PRD-2024-003',
          製品名: 'フレーム組立C',
          ライン名: 'ライン3',
          作業者名: '鈴木 次郎',
          優先度: 3,
          配信ステータス: 'failed'
        }
      ];
      renderDeliveryHistory([...rows, ...sampleData]);
    }
  });

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const keyword = container.querySelector('#search-input').value.toLowerCase();
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const filtered = rows.filter(row => 
        JSON.stringify(row).toLowerCase().includes(keyword)
      );
      renderDeliveryHistory(filtered);
    }
  });

  // プレビュー機能
  const previewModal = container.querySelector('#preview-modal');
  const previewContent = container.querySelector('#preview-content');

  container.querySelector('#btn-preview').addEventListener('click', () => {
    const instruction = container.querySelector('#instruction-select');
    const line = container.querySelector('#line-select');
    const worker = container.querySelector('#worker-select');
    const datetime = container.querySelector('#delivery-datetime');
    const priority = container.querySelector('#priority-select');

    if (!instruction.value || !line.value || !worker.value) {
      alert('配信対象指示書、製造ライン、配信先作業者を選択してください。');
      return;
    }

    previewContent.innerHTML = `
      <div style="margin-bottom: 1rem;">
        <strong>配信対象指示書:</strong> ${instruction.options[instruction.selectedIndex].text}
      </div>
      <div style="margin-bottom: 1rem;">
        <strong>製造ライン:</strong> ${line.options[line.selectedIndex].text}
      </div>
      <div style="margin-bottom: 1rem;">
        <strong>配信先作業者:</strong> ${worker.options[worker.selectedIndex].text}
      </div>
      <div style="margin-bottom: 1rem;">
        <strong>配信日時:</strong> ${formatDateTime(datetime.value)}
      </div>
      <div style="margin-bottom: 1rem;">
        <strong>優先度:</strong> ${priority.options[priority.selectedIndex].text}
      </div>
      <div style="padding: 1rem; background: var(--bg-main); border-radius: 4px; margin-top: 1rem;">
        <strong>配信メッセージ:</strong><br>
        生産指示書「${instruction.options[instruction.selectedIndex].text}」の作業を開始してください。<br>
        優先度: ${priority.options[priority.selectedIndex].text}<br>
        配信日時: ${formatDateTime(datetime.value)}
      </div>
    `;

    previewModal.style.display = 'block';
  });

  // プレビューモーダルを閉じる
  container.querySelector('#close-preview').addEventListener('click', () => {
    previewModal.style.display = 'none';
  });

  container.querySelector('#cancel-preview').addEventListener('click', () => {
    previewModal.style.display = 'none';
  });

  // 配信実行
  async function executeDelivery() {
    const instruction = container.querySelector('#instruction-select');
    const line = container.querySelector('#line-select');
    const worker = container.querySelector('#worker-select');
    const datetime = container.querySelector('#delivery-datetime');
    const priority = container.querySelector('#priority-select');
    const bulkDelivery = container.querySelector('#bulk-delivery');

    if (!instruction.value || !line.value || !worker.value) {
      alert('配信対象指示書、製造ライン、配信先作業者を選択してください。');
      return;
    }

    const deliveryData = {
      生産指示書ID: instruction.value,
      生産指示書番号: instruction.options[instruction.selectedIndex].text.split(' - ')[0],
      製品名: instruction.options[instruction.selectedIndex].text.split(' - ')[1],
      製造ラインID: line.value,
      ライン名: line.options[line.selectedIndex].text,
      作業者ID: worker.value,
      作業者名: worker.options[worker.selectedIndex].text,
      配信日時: datetime.value,
      優先度: parseInt(priority.value),
      一括配信フラグ: bulkDelivery.checked,
      配信ステータス: 'delivered',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(0, deliveryData);
    if (saved) {
      alert('配信を実行しました。');
      previewModal.style.display = 'none';

      // フォームをリセット
      instruction.selectedIndex = 0;
      line.selectedIndex = 0;
      worker.selectedIndex = 0;
      priority.selectedIndex = 1;
      bulkDelivery.checked = false;

      // 履歴を更新
      const rows = await window.aivicApi.list(0);
      if (rows) renderDeliveryHistory(rows);
    }
  }

  container.querySelector('#btn-delivery').addEventListener('click', executeDelivery);
  container.querySelector('#confirm-delivery').addEventListener('click', executeDelivery);

  // 再送機能
  container.addEventListener('click', async (e) => {
    const resendBtn = e.target.closest('.resend-btn');
    if (resendBtn) {
      const id = resendBtn.dataset.id;
      if (!confirm('この指示書を再送しますか？')) return;

      const updated = await window.aivicApi.update(0, id, {
        配信ステータス: 'delivered',
        配信日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      });

      if (updated) {
        alert('再送しました。');
        const rows = await window.aivicApi.list(0);
        if (rows) renderDeliveryHistory(rows);
      }
    }
  });

  // モーダル外クリックで閉じる
  previewModal.addEventListener('click', (e) => {
    if (e.target === previewModal) {
      previewModal.style.display = 'none';
    }
  });
}

function(container, apiUrl, tables) {
  let allResults = [];

  // テーブル再描画関数
  function renderResults(results) {
    const tbody = container.querySelector('#results-tbody');
    tbody.innerHTML = results.map(result => {
      const completionRate = result.生産予定数量 > 0 ? Math.round((result.生産実績数量 || 0) / result.生産予定数量 * 100) : 0;
      const statusColor = result.ステータス === '完了' ? '#4ade80' : result.ステータス === '進行中' ? '#fbbf24' : '#f87171';
      const qualityStatus = result.良品数量 && result.生産実績数量 ? 
        (result.良品数量 / result.生産実績数量 >= 0.95 ? '良好' : '要注意') : '未検査';

      return `
        <tr data-id="${result.生産指示書ID}" style="cursor: pointer;" class="result-row">
          <td>${result.生産指示書番号 || ''}</td>
          <td>${result.製品名 || ''}</td>
          <td>${result.ライン名 || ''}</td>
          <td>${result.生産予定数量 || 0}</td>
          <td>${result.生産実績数量 || 0}</td>
          <td>
            <div style="display: flex; align-items: center; gap: 0.5rem;">
              <div style="flex: 1; height: 8px; background: rgba(255,255,255,0.1); border-radius: 4px; overflow: hidden;">
                <div style="height: 100%; background: ${completionRate >= 100 ? '#4ade80' : '#fbbf24'}; width: ${Math.min(completionRate, 100)}%;"></div>
              </div>
              <span style="font-size: 0.85rem; color: var(--text-muted);">${completionRate}%</span>
            </div>
          </td>
          <td>
            <span style="padding: 0.2rem 0.5rem; border-radius: 12px; font-size: 0.8rem; background: ${qualityStatus === '良好' ? 'rgba(74, 222, 128, 0.2)' : 'rgba(251, 191, 36, 0.2)'}; color: ${qualityStatus === '良好' ? '#4ade80' : '#fbbf24'};">
              ${qualityStatus}
            </span>
          </td>
          <td>
            <span style="padding: 0.2rem 0.5rem; border-radius: 12px; font-size: 0.8rem; background: rgba(${statusColor.slice(1, 3)}, ${statusColor.slice(3, 5)}, ${statusColor.slice(5, 7)}, 0.2); color: ${statusColor};">
              ${result.ステータス || '未着手'}
            </span>
          </td>
          <td>${result.生産開始実績日時 ? new Date(result.生産開始実績日時).toLocaleString() : '-'}</td>
          <td>${result.生産完了実績日時 ? new Date(result.生産完了実績日時).toLocaleString() : '-'}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${result.生産指示書ID}" style="padding: 0.3rem 0.6rem; font-size: 0.8rem;">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    updateKPIs(results);
  }

  // KPI更新
  function updateKPIs(results) {
    const totalOrders = results.length;
    const completed = results.filter(r => r.ステータス === '完了').length;
    const inProgress = results.filter(r => r.ステータス === '進行中').length;

    container.querySelector('#kpi-total-orders').textContent = totalOrders;
    container.querySelector('#kpi-completed').textContent = completed;
    container.querySelector('#kpi-in-progress').textContent = inProgress;
  }

  // アラート表示
  function renderAlerts(alerts) {
    const alertList = container.querySelector('#alert-list');
    if (!alerts || alerts.length === 0) {
      alertList.innerHTML = '<div style="color: var(--text-muted); font-size: 0.9rem;">現在、異常値アラートはありません</div>';
      container.querySelector('#kpi-alerts').textContent = '0';
      return;
    }

    container.querySelector('#kpi-alerts').textContent = alerts.length;
    alertList.innerHTML = alerts.slice(0, 5).map(alert => `
      <div style="padding: 0.5rem; margin-bottom: 0.5rem; border-left: 3px solid ${alert.重要度 === '緊急' ? '#f87171' : '#fbbf24'}; background: var(--bg-main); border-radius: 4px;">
        <div style="font-size: 0.9rem; color: var(--text); margin-bottom: 0.2rem;">${alert.タイトル || ''}</div>
        <div style="font-size: 0.8rem; color: var(--text-muted);">${alert.メッセージ内容 || ''}</div>
        <div style="font-size: 0.75rem; color: var(--text-muted); margin-top: 0.2rem;">
          ${alert.作成日時 ? new Date(alert.作成日時).toLocaleString() : ''}
        </div>
      </div>
    `).join('');
  }

  // 詳細モーダル表示
  function showDetailModal(orderId) {
    const order = allResults.find(r => r.生産指示書ID === orderId);
    if (!order) return;

    const modal = container.querySelector('#detail-modal');
    const content = container.querySelector('#detail-content');

    content.innerHTML = `
      <div>
        <h5 style="margin: 0 0 0.5rem 0; color: var(--text);">基本情報</h5>
        <div style="font-size: 0.9rem; line-height: 1.6;">
          <div><strong>指示書番号:</strong> ${order.生産指示書番号 || ''}</div>
          <div><strong>製品名:</strong> ${order.製品名 || ''}</div>
          <div><strong>製造ライン:</strong> ${order.ライン名 || ''}</div>
          <div><strong>優先度:</strong> ${order.優先度 || ''}</div>
        </div>
      </div>
      <div>
        <h5 style="margin: 0 0 0.5rem 0; color: var(--text);">生産実績</h5>
        <div style="font-size: 0.9rem; line-height: 1.6;">
          <div><strong>計画数量:</strong> ${order.生産予定数量 || 0}</div>
          <div><strong>実績数量:</strong> ${order.生産実績数量 || 0}</div>
          <div><strong>良品数量:</strong> ${order.良品数量 || 0}</div>
          <div><strong>不良品数量:</strong> ${order.不良品数量 || 0}</div>
        </div>
      </div>
      <div>
        <h5 style="margin: 0 0 0.5rem 0; color: var(--text);">日程</h5>
        <div style="font-size: 0.9rem; line-height: 1.6;">
          <div><strong>開始予定:</strong> ${order.生産開始予定日時 ? new Date(order.生産開始予定日時).toLocaleString() : '-'}</div>
          <div><strong>完了予定:</strong> ${order.生産完了予定日時 ? new Date(order.生産完了予定日時).toLocaleString() : '-'}</div>
          <div><strong>実際開始:</strong> ${order.生産開始実績日時 ? new Date(order.生産開始実績日時).toLocaleString() : '-'}</div>
          <div><strong>実際完了:</strong> ${order.生産完了実績日時 ? new Date(order.生産完了実績日時).toLocaleString() : '-'}</div>
        </div>
      </div>
      <div>
        <h5 style="margin: 0 0 0.5rem 0; color: var(--text);">備考</h5>
        <div style="font-size: 0.9rem; color: var(--text-muted);">
          ${order.備考 || '特記事項なし'}
        </div>
      </div>
    `;

    // 工程別進捗グラフ描画
    drawProgressChart(order);

    modal.style.display = 'block';
  }

  // 工程別進捗グラフ描画
  function drawProgressChart(order) {
    const canvas = container.querySelector('#progress-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプル工程データ
    const processes = [
      { name: '材料準備', progress: 100, status: '完了' },
      { name: '加工', progress: 85, status: '進行中' },
      { name: '組立', progress: 60, status: '進行中' },
      { name: '検査', progress: 0, status: '未着手' },
      { name: '梱包', progress: 0, status: '未着手' }
    ];

    const barHeight = 25;
    const barSpacing = 35;
    const startY = 20;
    const startX = 100;
    const barWidth = 400;

    processes.forEach((process, index) => {
      const y = startY + index * barSpacing;

      // 工程名
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px sans-serif';
      ctx.fillText(process.name, 10, y + 16);

      // 背景バー
      ctx.fillStyle = '#2a3441';
      ctx.fillRect(startX, y, barWidth, barHeight);

      // 進捗バー
      const progressWidth = (barWidth * process.progress) / 100;
      ctx.fillStyle = process.status === '完了' ? '#4ade80' : process.status === '進行中' ? '#fbbf24' : '#6b7280';
      ctx.fillRect(startX, y, progressWidth, barHeight);

      // 進捗率テキスト
      ctx.fillStyle = '#d0e4ff';
      ctx.fillText(`${process.progress}%`, startX + barWidth + 10, y + 16);
    });
  }

  // CSVエクスポート
  function exportCSV() {
    if (allResults.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['指示書番号', '製品名', '製造ライン', '計画数量', '実績数量', '良品数量', '不良品数量', 'ステータス', '開始日時', '完了日時'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...allResults.map(row => [
        `"${row.生産指示書番号 || ''}"`,
        `"${row.製品名 || ''}"`,
        `"${row.ライン名 || ''}"`,
        row.生産予定数量 || 0,
        row.生産実績数量 || 0,
        row.良品数量 || 0,
        row.不良品数量 || 0,
        `"${row.ステータス || ''}"`,
        `"${row.生産開始実績日時 ? new Date(row.生産開始実績日時).toLocaleString() : ''}"`,
        `"${row.生産完了実績日時 ? new Date(row.生産完了実績日時).toLocaleString() : ''}"`,
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `生産実績_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const orders = await window.aivicApi.list(4); // 生産指示書
      const lines = await window.aivicApi.list(3); // 製造ライン
      const products = await window.aivicApi.list(0); // 製品マスタ
      const alerts = await window.aivicApi.list(12); // アラート通知

      // データ結合
      allResults = orders.map(order => {
        const line = lines.find(l => l.ライン_ID === order.製造ラインID);
        const product = products.find(p => p.製品ID === order.製品ID);
        return {
          ...order,
          ライン名: line?.ライン名 || '',
          製品名: product?.製品名 || ''
        };
      });

      renderResults(allResults);
      renderAlerts(alerts);

    } catch (error) {
      console.error('データ読み込みエラー:', error);
      renderResults(tables[4]?.records || []);
      renderAlerts([]);
    }
  }

  // 検索実行
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const orderNo = container.querySelector('#search-order-no').value.trim();
    const productName = container.querySelector('#search-product-name').value.trim();
    const line = container.querySelector('#search-line').value;
    const startDate = container.querySelector('#search-start-date').value;
    const endDate = container.querySelector('#search-end-date').value;

    let filtered = allResults;

    if (orderNo) {
      filtered = filtered.filter(r => (r.生産指示書番号 || '').includes(orderNo));
    }
    if (productName) {
      filtered = filtered.filter(r => (r.製品名 || '').includes(productName));
    }
    if (line) {
      filtered = filtered.filter(r => r.ライン名 === line);
    }
    if (startDate) {
      filtered = filtered.filter(r => r.生産開始実績日時 && new Date(r.生産開始実績日時) >= new Date(startDate));
    }
    if (endDate) {
      filtered = filtered.filter(r => r.生産完了実績日時 && new Date(r.生産完了実績日時) <= new Date(endDate + 'T23:59:59'));
    }

    renderResults(filtered);
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 詳細表示・モーダル制御
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
      return;
    }

    const resultRow = e.target.closest('.result-row');
    if (resultRow && !e.target.closest('button')) {
      showDetailModal(resultRow.dataset.id);
      return;
    }

    if (e.target.id === 'close-modal' || e.target.id === 'detail-modal') {
      container.querySelector('#detail-modal').style.display = 'none';
    }
  });

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  let selectedOrderId = null;

  // 生産指示書一覧の再描画
  function renderOrders(orders) {
    const tbody = container.querySelector("#order-tbody");
    tbody.innerHTML = orders.map(order => `
      <tr data-id="${order.生産指示書ID}" style="cursor: pointer; border-bottom: 1px solid var(--border);" 
          class="order-row">
        <td style="padding: 0.5rem; color: var(--text);">${order.生産指示書番号 || ""}</td>
        <td style="padding: 0.5rem; color: var(--text);">${order.製品名 || ""}</td>
      </tr>
    `).join("");
  }

  // 初期データ表示
  const productionOrders = tables.find(t => t.tableName === "生産指示書");
  if (productionOrders) {
    renderOrders(productionOrders.records || []);
  }

  // 生産指示書検索
  container.querySelector("#btn-search-order").addEventListener("click", async () => {
    const keyword = container.querySelector("#production-order-search").value.trim();
    try {
      const orders = await window.aivicApi.list(tables.findIndex(t => t.tableName === "生産指示書"));
      if (orders) {
        const filtered = keyword ? 
          orders.filter(order => 
            (order.生産指示書番号 || "").includes(keyword) ||
            (order.製品名 || "").includes(keyword)
          ) : orders;
        renderOrders(filtered);
      }
    } catch (error) {
      console.error("検索エラー:", error);
    }
  });

  // 生産指示書選択
  container.addEventListener("click", (e) => {
    const orderRow = e.target.closest(".order-row");
    if (orderRow) {
      selectedOrderId = orderRow.dataset.id;

      // 選択行のハイライト
      container.querySelectorAll(".order-row").forEach(row => {
        row.style.background = "";
      });
      orderRow.style.background = "rgba(var(--primary-rgb, 59, 130, 246), 0.1)";

      // 選択した生産指示書の情報を表示
      const orderNumber = orderRow.querySelector("td:first-child").textContent;
      const productName = orderRow.querySelector("td:nth-child(2)").textContent;

      container.querySelector("#display-order-number").textContent = orderNumber;
      container.querySelector("#display-product-name").textContent = productName;
      container.querySelector("#display-line-name").textContent = "ライン A"; // 仮の値

      // フォーム表示
      container.querySelector("#selected-order-info").style.display = "block";
      container.querySelector("#progress-form").style.display = "block";
      container.querySelector("#initial-message").style.display = "none";

      // 現在時刻を開始時刻にセット
      const now = new Date();
      now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
      container.querySelector("#start-time").value = now.toISOString().slice(0, 16);
    }
  });

  // フォームクリア
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#process-select").value = "";
    container.querySelector("#worker-select").value = "";
    container.querySelector("#progress-rate").value = "";
    container.querySelector("#start-time").value = "";
    container.querySelector("#end-time").value = "";
    container.querySelector("#actual-quantity").value = "";
    container.querySelector("#defect-quantity").value = "";
    container.querySelector("#remarks").value = "";
    container.querySelectorAll('input[name="quality-result"]').forEach(radio => radio.checked = false);
  });

  // 進捗更新保存
  container.querySelector("#btn-save-progress").addEventListener("click", async () => {
    if (!selectedOrderId) {
      alert("生産指示書を選択してください");
      return;
    }

    const processId = container.querySelector("#process-select").value;
    const workerId = container.querySelector("#worker-select").value;
    const progressRate = container.querySelector("#progress-rate").value;
    const startTime = container.querySelector("#start-time").value;
    const endTime = container.querySelector("#end-time").value;
    const actualQuantity = container.querySelector("#actual-quantity").value;
    const defectQuantity = container.querySelector("#defect-quantity").value;
    const qualityResult = container.querySelector('input[name="quality-result"]:checked')?.value;
    const remarks = container.querySelector("#remarks").value;

    if (!processId || !workerId || !progressRate) {
      alert("工程、作業者、進捗率は必須項目です");
      return;
    }

    try {
      // 進捗管理テーブルに保存
      const progressTableIndex = tables.findIndex(t => t.tableName === "進捗管理");
      if (progressTableIndex >= 0) {
        const progressData = {
          生産指示書ID: selectedOrderId,
          工程ID: processId,
          製造ラインID: "1", // 仮の値
          計画開始日時: startTime,
          計画終了日時: endTime,
          実績開始日時: startTime,
          実績終了日時: endTime,
          計画数量: parseInt(actualQuantity) || 0,
          完了数量: parseInt(actualQuantity) || 0,
          良品数量: (parseInt(actualQuantity) || 0) - (parseInt(defectQuantity) || 0),
          不良品数量: parseInt(defectQuantity) || 0,
          進捗率: parseInt(progressRate),
          工程ステータス: progressRate == 100 ? "完了" : "進行中",
          遅延フラグ: false,
          備考: remarks,
          作成者ID: "current-user",
          更新者ID: "current-user"
        };

        const saved = await window.aivicApi.save(progressTableIndex, progressData);
        if (saved) {
          alert("進捗を更新しました");

          // 作業実績も同時に記録
          const workResultTableIndex = tables.findIndex(t => t.tableName === "作業実績");
          if (workResultTableIndex >= 0) {
            const workResultData = {
              生産指示書ID: selectedOrderId,
              製造ラインID: "1",
              工程ID: processId,
              作業開始日時: startTime,
              作業終了日時: endTime,
              実績数量: parseInt(actualQuantity) || 0,
              良品数量: (parseInt(actualQuantity) || 0) - (parseInt(defectQuantity) || 0),
              不良品数量: parseInt(defectQuantity) || 0,
              作業者ID: workerId,
              作業状況: endTime ? "完了" : "進行中",
              備考: remarks,
              作成者ID: "current-user"
            };
            await window.aivicApi.save(workResultTableIndex, workResultData);
          }

          // 品質検査結果も記録
          if (qualityResult) {
            const qualityTableIndex = tables.findIndex(t => t.tableName === "品質検査結果");
            if (qualityTableIndex >= 0) {
              const qualityData = {
                生産指示書ID: selectedOrderId,
                製品ID: "1", // 仮の値
                工程ID: processId,
                検査項目名: "工程検査",
                判定結果: qualityResult,
                検査数量: parseInt(actualQuantity) || 0,
                不良数量: parseInt(defectQuantity) || 0,
                検査日時: new Date().toISOString(),
                検査者ID: workerId,
                備考: remarks,
                作成者ID: "current-user"
              };
              await window.aivicApi.save(qualityTableIndex, qualityData);
            }
          }

          // フォームクリア
          container.querySelector("#btn-clear").click();
        }
      }
    } catch (error) {
      console.error("保存エラー:", error);
      alert("保存に失敗しました");
    }
  });
}

function(container, apiUrl, tables) {
