  function renderMaterials() {
    const tbody = container.querySelector("#material-tbody");
    tbody.innerHTML = materialList.map((m, index) => `
      <tr>
        <td>${m.name}</td>
        <td>${m.usage}</td>
        <td>
          <button class="action-btn secondary remove-material-btn" data-index="${index}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 0.25rem 0.5rem; border-radius: 3px; font-size: 0.8rem;">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データ描画
  renderWorkResults(tables[0]?.records || []);
  renderMaterials();

  // 3. 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value;
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const filtered = rows.filter(r => JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase()));
      renderWorkResults(filtered);
    }
  });

  // 4. 実績登録
  container.querySelector("#btn-save").addEventListener("click", async () => {
    const form = container.querySelector("#work-result-form");
    const formData = new FormData(form);

    const data = {
      生産指示書ID: formData.get("productionOrderId"),
      工程ID: formData.get("processId"),
      作業者ID: formData.get("workerId"),
      作業開始日時: formData.get("startTime"),
      作業終了日時: formData.get("endTime"),
      実績数量: parseInt(formData.get("actualQuantity")) || 0,
      良品数量: parseInt(formData.get("goodQuantity")) || 0,
      不良品数量: parseInt(formData.get("defectQuantity")) || 0,
      不良理由: formData.get("defectReason"),
      作業状況: "完了",
      使用資材: JSON.stringify(materialList),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(0, data);
    if (saved) {
      const rows = await window.aivicApi.list(0);
      if (rows) renderWorkResults(rows);
      form.reset();
      materialList = [];
      renderMaterials();
      alert("作業実績を登録しました");
    }
  });

  // 5. フォームクリア
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#work-result-form").reset();
    materialList = [];
    renderMaterials();
  });

  // 6. 資材追加
  container.querySelector("#btn-add-material").addEventListener("click", () => {
    const materialSelect = container.querySelector("#material-select");
    const usageInput = container.querySelector("#material-usage");

    if (materialSelect.value && usageInput.value) {
      const materialName = materialSelect.options[materialSelect.selectedIndex].text;
      materialList.push({
        id: materialSelect.value,
        name: materialName,
        usage: parseFloat(usageInput.value)
      });

      renderMaterials();
      materialSelect.value = "";
      usageInput.value = "";
    }
  });

  // 7. 生産指示書選択時の製品名表示
  container.querySelector('select[name="productionOrderId"]').addEventListener("change", (e) => {
    const productNameDisplay = container.querySelector("#product-name-display");
    const selectedOption = e.target.options[e.target.selectedIndex];
    if (selectedOption.value) {
      // 生産指示書のテキストから製品名を抽出（簡易実装）
      const text = selectedOption.text;
      const productMatch = text.match(/製品[A-Z]/);
      productNameDisplay.value = productMatch ? productMatch[0] : "";
    } else {
      productNameDisplay.value = "";
    }
  });

  // 8. CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (rows && rows.length > 0) {
      const headers = ["生産指示書ID", "工程ID", "作業者ID", "作業開始日時", "作業終了日時", "実績数量", "良品数量", "不良品数量"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...rows.map(r => [
          r.生産指示書ID || "",
          r.工程ID || "",
          r.作業者ID || "",
          r.作業開始日時 || "",
          r.作業終了日時 || "",
          r.実績数量 || "",
          r.良品数量 || "",
          r.不良品数量 || ""
        ].map(field => `"${field}"`).join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "work_results.csv";
      link.click();
    }
  });

  // 9. イベントデリゲーション（編集・削除・資材削除）
  container.addEventListener("click", async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この作業実績を削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderWorkResults(rows);
      return;
    }

    // 編集ボタン
    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      // 簡易実装：該当行のデータをフォームに設定
      const row = editBtn.closest("tr");
      const cells = row.querySelectorAll("td");
      if (cells.length >= 9) {
        container.querySelector('select[name="productionOrderId"]').value = cells[0].textContent;
        container.querySelector('input[name="workerId"]').value = cells[3].textContent;
        container.querySelector('input[name="startTime"]').value = cells[4].textContent;
        container.querySelector('input[name="endTime"]').value = cells[5].textContent;
        container.querySelector('input[name="actualQuantity"]').value = cells[6].textContent;
        container.querySelector('input[name="goodQuantity"]').value = cells[7].textContent;
        container.querySelector('input[name="defectQuantity"]').value = cells[8].textContent;
      }
      return;
    }

    // 資材削除ボタン
    const removeMaterialBtn = e.target.closest(".remove-material-btn");
    if (removeMaterialBtn) {
      const index = parseInt(removeMaterialBtn.dataset.index);
      materialList.splice(index, 1);
      renderMaterials();
      return;
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#results-tbody");

  // 1. テーブル再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(row => {
      const progressRate = Math.round((row.完了数量 || 0) / (row.計画数量 || 1) * 100);
      const statusBadge = getStatusBadge(row.工程ステータス);
      const qualityIcon = getQualityIcon(row.良品数量, row.不良品数量);
      const alertIcon = getAlertIcon(row.遅延フラグ, row.不良品数量);

      return `
        <tr data-id="${row.id}" style="border-bottom: 1px solid var(--border); cursor: pointer;">
          <td style="padding: 0.75rem; color: var(--text); border-right: 1px solid var(--border);">${row.生産指示書番号 || ""}</td>
          <td style="padding: 0.75rem; color: var(--text); border-right: 1px solid var(--border);">${row.製品名 || ""}</td>
          <td style="padding: 0.75rem; color: var(--text); border-right: 1px solid var(--border);">${row.ライン名 || ""}</td>
          <td style="padding: 0.75rem; color: var(--text); border-right: 1px solid var(--border);">${row.工程名 || ""}</td>
          <td style="padding: 0.75rem; text-align: center; color: var(--text); border-right: 1px solid var(--border);">${row.計画数量 || 0}</td>
          <td style="padding: 0.75rem; text-align: center; color: var(--text); border-right: 1px solid var(--border);">${row.完了数量 || 0}</td>
          <td style="padding: 0.75rem; text-align: center; color: var(--text); border-right: 1px solid var(--border);">${row.良品数量 || 0}</td>
          <td style="padding: 0.75rem; text-align: center; color: var(--text); border-right: 1px solid var(--border);">${row.不良品数量 || 0}</td>
          <td style="padding: 0.75rem; text-align: center; color: var(--text); border-right: 1px solid var(--border);">
            <div style="display: flex; align-items: center; gap: 0.5rem;">
              <div style="flex: 1; height: 6px; background: rgba(255,255,255,0.1); border-radius: 3px; overflow: hidden;">
                <div style="height: 100%; background: ${progressRate >= 100 ? '#22c55e' : progressRate >= 80 ? '#f59e0b' : '#3b82f6'}; width: ${Math.min(progressRate, 100)}%; transition: width 0.3s;"></div>
              </div>
              <span style="font-size: 0.75rem; min-width: 35px;">${progressRate}%</span>
            </div>
          </td>
          <td style="padding: 0.75rem; text-align: center; border-right: 1px solid var(--border);">${statusBadge}</td>
          <td style="padding: 0.75rem; text-align: center; border-right: 1px solid var(--border);">${qualityIcon}</td>
          <td style="padding: 0.75rem; text-align: center; border-right: 1px solid var(--border);">${alertIcon}</td>
          <td style="padding: 0.75rem; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${row.id}" style="padding: 0.25rem 0.5rem; font-size: 0.75rem; background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); border-radius: 3px;">製造履歴詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  function getStatusBadge(status) {
    const statusMap = {
      '未着手': { color: '#6b7280', bg: 'rgba(107, 114, 128, 0.1)' },
      '進行中': { color: '#3b82f6', bg: 'rgba(59, 130, 246, 0.1)' },
      '完了': { color: '#22c55e', bg: 'rgba(34, 197, 94, 0.1)' },
      '中断': { color: '#f59e0b', bg: 'rgba(245, 158, 11, 0.1)' },
      '遅延': { color: '#ef4444', bg: 'rgba(239, 68, 68, 0.1)' }
    };
    const style = statusMap[status] || statusMap['未着手'];
    return `<span style="padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.75rem; background: ${style.bg}; color: ${style.color};">${status || '未着手'}</span>`;
  }

  function getQualityIcon(goodCount, defectCount) {
    const total = (goodCount || 0) + (defectCount || 0);
    if (total === 0) return '<span style="color: var(--text-muted);">-</span>';

    const defectRate = (defectCount || 0) / total;
    if (defectRate === 0) return '<span style="color: #22c55e;">✓</span>';
    if (defectRate < 0.05) return '<span style="color: #f59e0b;">△</span>';
    return '<span style="color: #ef4444;">✗</span>';
  }

  function getAlertIcon(delayFlag, defectCount) {
    if (delayFlag || (defectCount && defectCount > 0)) {
      return '<span style="color: #ef4444; font-size: 1rem;">⚠</span>';
    }
    return '<span style="color: var(--text-muted);">-</span>';
  }

  // 2. 初期データ描画
  const initialData = tables[11]?.records || []; // 進捗管理テーブル
  renderRows(initialData);

  // 3. 検索ボタンイベント
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const lineFilter = container.querySelector("#line-select").value;
    const productFilter = container.querySelector("#product-search").value.toLowerCase();
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const processFilters = Array.from(container.querySelectorAll('input[type="checkbox"]:checked')).map(cb => cb.value);

    const allRows = await window.aivicApi.list(11);
    if (!allRows) return;

    const filteredRows = allRows.filter(row => {
      if (lineFilter && row.ライン名 !== lineFilter) return false;
      if (productFilter && !row.製品名?.toLowerCase().includes(productFilter)) return false;
      if (startDate && row.計画開始日時 && new Date(row.計画開始日時) < new Date(startDate)) return false;
      if (endDate && row.計画開始日時 && new Date(row.計画開始日時) > new Date(endDate + 'T23:59:59')) return false;
      if (processFilters.length > 0 && !processFilters.includes(row.工程名)) return false;
      return true;
    });

    renderRows(filteredRows);
  });

  // 4. クリアボタンイベント
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#line-select").value = "";
    container.querySelector("#product-search").value = "";
    container.querySelector("#start-date").value = "";
    container.querySelector("#end-date").value = "";
    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);
    renderRows(initialData);
  });

  // 5. CSVエクスポート
  container.querySelector("#btn-csv-export").addEventListener("click", async () => {
    const allRows = await window.aivicApi.list(11);
    if (!allRows) return;

    const headers = ['生産指示書番号', '製品名', '製造ライン', '工程', '予定数量', '実績数量', '良品数量', '不良品数量', '進捗率', 'ステータス'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...allRows.map(row => [
        row.生産指示書番号 || '',
        row.製品名 || '',
        row.ライン名 || '',
        row.工程名 || '',
        row.計画数量 || 0,
        row.完了数量 || 0,
        row.良品数量 || 0,
        row.不良品数量 || 0,
        Math.round((row.完了数量 || 0) / (row.計画数量 || 1) * 100) + '%',
        row.工程ステータス || '未着手'
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '生産実績_' + new Date().toISOString().slice(0, 10) + '.csv';
    link.click();
  });

  // 6. 行レベル操作（詳細画面遷移）
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      window.showScreen("scr-1780995311464");
    }
  });
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allRecords = [];
  let filteredRecords = [];

  // ステータスバッジのスタイル
  function getStatusBadge(status) {
    const statusMap = {
      '完了': { bg: '#10b981', text: '#ffffff' },
      '進行中': { bg: '#f59e0b', text: '#ffffff' },
      '未着手': { bg: '#6b7280', text: '#ffffff' },
      '中止': { bg: '#ef4444', text: '#ffffff' }
    };
    const style = statusMap[status] || { bg: '#6b7280', text: '#ffffff' };
    return `<span style="background: ${style.bg}; color: ${style.text}; padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.75rem;">${status}</span>`;
  }

  // テーブル再描画関数
  function renderRows(records) {
    const tbody = container.querySelector('#history-tbody');
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageRecords = records.slice(startIndex, endIndex);

    tbody.innerHTML = pageRecords.map(r => `
      <tr data-id="${r.生産指示書ID || r.id || ''}" style="cursor: pointer;">
        <td>${r.生産指示書番号 || ''}</td>
        <td>${r.製品名 || ''}</td>
        <td>${r.ライン名 || ''}</td>
        <td>${r.工程名 || ''}</td>
        <td>${r.ロット番号 || 'LOT-' + Math.random().toString(36).substr(2, 8).toUpperCase()}</td>
        <td style="text-align: right;">${(r.生産実績数量 || r.実績数量 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${(r.良品数量 || 0).toLocaleString()}</td>
        <td style="text-align: right;">${(r.不良品数量 || 0).toLocaleString()}</td>
        <td>${r.生産開始実績日時 ? new Date(r.生産開始実績日時).toLocaleString() : ''}</td>
        <td>${r.生産完了実績日時 ? new Date(r.生産完了実績日時).toLocaleString() : ''}</td>
        <td>${getStatusBadge(r.ステータス || '未着手')}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.生産指示書ID || r.id || ''}" style="padding: 0.25rem 0.5rem; font-size: 0.8rem;">詳細</button>
        </td>
      </tr>
    `).join('');

    updatePagination(records.length);
  }

  // ページネーション更新
  function updatePagination(totalItems) {
    const totalPages = Math.ceil(totalItems / itemsPerPage);
    const pageInfo = container.querySelector('#page-info');
    const btnPrev = container.querySelector('#btn-prev');
    const btnNext = container.querySelector('#btn-next');

    pageInfo.textContent = `${currentPage} / ${totalPages}`;
    btnPrev.disabled = currentPage <= 1;
    btnNext.disabled = currentPage >= totalPages;
  }

  // 検索フィルター
  function applyFilters() {
    const productName = container.querySelector('#product-name-search').value.toLowerCase();
    const dateFrom = container.querySelector('#date-from').value;
    const dateTo = container.querySelector('#date-to').value;
    const lineFilter = container.querySelector('#line-filter').value;
    const lotNumber = container.querySelector('#lot-number-search').value.toLowerCase();

    const checkedProcesses = Array.from(container.querySelectorAll('input[type="checkbox"]:checked')).map(cb => cb.value);

    filteredRecords = allRecords.filter(record => {
      // 製品名フィルター
      if (productName && !(record.製品名 || '').toLowerCase().includes(productName)) return false;

      // 製造ラインフィルター
      if (lineFilter && record.ライン名 !== lineFilter) return false;

      // ロット番号フィルター
      if (lotNumber && !(record.ロット番号 || '').toLowerCase().includes(lotNumber)) return false;

      // 工程フィルター
      if (checkedProcesses.length > 0 && !checkedProcesses.includes(record.工程名)) return false;

      // 日付フィルター
      if (dateFrom || dateTo) {
        const recordDate = record.生産開始実績日時 ? new Date(record.生産開始実績日時).toISOString().split('T')[0] : '';
        if (dateFrom && recordDate < dateFrom) return false;
        if (dateTo && recordDate > dateTo) return false;
      }

      return true;
    });

    currentPage = 1;
    renderRows(filteredRecords);
  }

  // CSV出力
  function exportCSV() {
    const headers = ['生産指示書番号', '製品名', '製造ライン', '工程', 'ロット番号', '生産数量', '良品数量', '不良品数量', '開始日時', '完了日時', 'ステータス'];
    const csvContent = [
      headers.join(','),
      ...filteredRecords.map(r => [
        r.生産指示書番号 || '',
        r.製品名 || '',
        r.ライン名 || '',
        r.工程名 || '',
        r.ロット番号 || '',
        r.生産実績数量 || r.実績数量 || 0,
        r.良品数量 || 0,
        r.不良品数量 || 0,
        r.生産開始実績日時 ? new Date(r.生産開始実績日時).toLocaleString() : '',
        r.生産完了実績日時 ? new Date(r.生産完了実績日時).toLocaleString() : '',
        r.ステータス || ''
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `製造履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
