          良品数量: Math.floor(Math.random() * 450) + 90,
          不良品数量: Math.floor(Math.random() * 20),
          生産開始実績日時: new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000).toISOString(),
          生産完了実績日時: new Date(Date.now() - Math.random() * 20 * 24 * 60 * 60 * 1000).toISOString(),
          ステータス: ['完了', '進行中', '未着手'][Math.floor(Math.random() * 3)],
          備考: i % 3 === 0 ? '品質検査で軽微な調整が必要でした。' : ''
        }));
      }

      filteredRecords = [...allRecords];
      renderRows(filteredRecords);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      // エラー時は初期データを使用
      allRecords = tables[4]?.records || [];
      filteredRecords = [...allRecords];
      renderRows(filteredRecords);
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#product-name-search').value = '';
    container.querySelector('#date-from').value = '';
    container.querySelector('#date-to').value = '';
    container.querySelector('#line-filter').value = '';
    container.querySelector('#lot-number-search').value = '';
    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);
    filteredRecords = [...allRecords];
    currentPage = 1;
    renderRows(filteredRecords);
  });

  container.querySelector('#btn-csv-export').addEventListener('click', exportCSV);

  container.querySelector('#btn-work-detail').addEventListener('click', () => {
    window.showScreen("scr-1780995322568");
  });

  // ページネーション
  container.querySelector('#btn-prev').addEventListener('click', () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredRecords);
    }
  });

  container.querySelector('#btn-next').addEventListener('click', () => {
    const totalPages = Math.ceil(filteredRecords.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredRecords);
    }
  });

  // モーダル制御
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#detail-modal').style.display = 'none';
  });

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
      return;
    }

    // 行クリックで詳細表示
    const row = e.target.closest('tr[data-id]');
    if (row && !e.target.closest('button')) {
      showDetail(row.dataset.id);
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector('#detail-modal').addEventListener('click', (e) => {
    if (e.target.id === 'detail-modal') {
      container.querySelector('#detail-modal').style.display = 'none';
    }
  });

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#work-results-tbody");
  let selectedRowId = null;

  // 1. 再描画関数の定義
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const startTime = r.作業開始日時 ? new Date(r.作業開始日時).toLocaleString('ja-JP') : '-';
      const endTime = r.作業終了日時 ? new Date(r.作業終了日時).toLocaleString('ja-JP') : '-';

      let statusBadge = '';
      switch(r.作業状況) {
        case '完了':
          statusBadge = `<span style="padding: 0.2rem 0.5rem; border-radius: 3px; background: rgba(34, 197, 94, 0.2); color: #22c55e; font-size: 0.8em;">${r.作業状況}</span>`;
          break;
        case '進行中':
          statusBadge = `<span style="padding: 0.2rem 0.5rem; border-radius: 3px; background: rgba(59, 130, 246, 0.2); color: #3b82f6; font-size: 0.8em;">${r.作業状況}</span>`;
          break;
        case '中断':
          statusBadge = `<span style="padding: 0.2rem 0.5rem; border-radius: 3px; background: rgba(239, 68, 68, 0.2); color: #ef4444; font-size: 0.8em;">${r.作業状況}</span>`;
          break;
        default:
          statusBadge = `<span style="padding: 0.2rem 0.5rem; border-radius: 3px; background: rgba(156, 163, 175, 0.2); color: #9ca3af; font-size: 0.8em;">${r.作業状況 || '未設定'}</span>`;
      }

      return `
        <tr data-id="${r.作業実績ID}" style="cursor: pointer; border-bottom: 1px solid var(--border);" class="work-row">
          <td style="padding: 0.6rem; color: var(--text); font-size: 0.9em;">${r.生産指示書番号 || '-'}</td>
          <td style="padding: 0.6rem; color: var(--text); font-size: 0.9em;">${r.製品名 || '-'}</td>
          <td style="padding: 0.6rem; color: var(--text); font-size: 0.9em;">${r.工程名 || '-'}</td>
          <td style="padding: 0.6rem; color: var(--text); font-size: 0.9em;">${r.ライン名 || '-'}</td>
          <td style="padding: 0.6rem; color: var(--text); font-size: 0.9em;">${r.作業者名 || '-'}</td>
          <td style="padding: 0.6rem; text-align: center; color: var(--text); font-size: 0.9em;">${r.実績数量 || 0}</td>
          <td style="padding: 0.6rem; text-align: center; color: var(--text); font-size: 0.9em;">${r.良品数量 || 0}</td>
          <td style="padding: 0.6rem; text-align: center;">${statusBadge}</td>
          <td style="padding: 0.6rem; text-align: center; color: var(--text-muted); font-size: 0.85em;">${startTime}</td>
          <td style="padding: 0.6rem; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${r.作業実績ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 0.3rem 0.6rem; border-radius: 3px; font-size: 0.8em; cursor: pointer;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 詳細パネル更新関数
  function updateDetailPanel(workResult) {
    if (!workResult) {
      container.querySelector("#detail-start-time").textContent = '-';
      container.querySelector("#detail-end-time").textContent = '-';
      container.querySelector("#detail-duration").textContent = '-';
      container.querySelector("#detail-notes").textContent = '-';
      return;
    }

    const startTime = workResult.作業開始日時 ? new Date(workResult.作業開始日時).toLocaleString('ja-JP') : '-';
    const endTime = workResult.作業終了日時 ? new Date(workResult.作業終了日時).toLocaleString('ja-JP') : '-';

    let duration = '-';
    if (workResult.作業開始日時 && workResult.作業終了日時) {
      const start = new Date(workResult.作業開始日時);
      const end = new Date(workResult.作業終了日時);
      const diffMs = end - start;
      const hours = Math.floor(diffMs / (1000 * 60 * 60));
      const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
      duration = `${hours}時間${minutes}分`;
    }

    container.querySelector("#detail-start-time").textContent = startTime;
    container.querySelector("#detail-end-time").textContent = endTime;
    container.querySelector("#detail-duration").textContent = duration;
    container.querySelector("#detail-notes").textContent = workResult.備考 || '-';
  }

  // 品質検査結果パネル更新関数
  async function updateQualityPanel(workResultId) {
    try {
      const qualityResults = await window.aivicApi.list(6); // 品質検査結果テーブル
      const relatedQuality = qualityResults?.find(q => q.生産指示書ID === workResultId);

      if (relatedQuality) {
        container.querySelector("#quality-item").textContent = relatedQuality.検査項目名 || '-';
        container.querySelector("#quality-count").textContent = relatedQuality.検査数量 || '-';
        container.querySelector("#quality-defect").textContent = relatedQuality.不良数量 || '-';

        const resultEl = container.querySelector("#quality-result-status");
        const result = relatedQuality.判定結果 || '-';
        resultEl.textContent = result;

        // 判定結果に応じて色を変更
        if (result === '合格') {
          resultEl.style.background = 'rgba(34, 197, 94, 0.2)';
          resultEl.style.color = '#22c55e';
        } else if (result === '不合格') {
          resultEl.style.background = 'rgba(239, 68, 68, 0.2)';
          resultEl.style.color = '#ef4444';
        } else {
          resultEl.style.background = 'rgba(156, 163, 175, 0.2)';
          resultEl.style.color = '#9ca3af';
        }
      } else {
        container.querySelector("#quality-item").textContent = '-';
        container.querySelector("#quality-result-status").textContent = '-';
        container.querySelector("#quality-count").textContent = '-';
        container.querySelector("#quality-defect").textContent = '-';
      }
    } catch (error) {
      console.error('品質検査結果の取得に失敗:', error);
    }
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(5).then(rows => {
    if (rows) {
      renderRows(rows);
    }
  });

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const lineId = container.querySelector("#line-select").value;
    const productName = container.querySelector("#product-search").value;
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const workerSelect = container.querySelector("#worker-select").value;

    const checkedProcesses = Array.from(container.querySelectorAll('input[type="checkbox"]:checked'))
      .map(cb => cb.value);

    const rows = await window.aivicApi.list(5);
    if (!rows) return;

    const filtered = rows.filter(r => {
      // 製造ライン絞り込み
      if (lineId && r.製造ラインID !== lineId) return false;

      // 製品名絞り込み
      if (productName && !r.製品名?.includes(productName)) return false;

      // 日付範囲絞り込み
      if (startDate && r.作業開始日時) {
        const workDate = new Date(r.作業開始日時).toISOString().split('T')[0];
        if (workDate < startDate) return false;
      }
      if (endDate && r.作業開始日時) {
        const workDate = new Date(r.作業開始日時).toISOString().split('T')[0];
        if (workDate > endDate) return false;
      }

      // 工程絞り込み
      if (checkedProcesses.length > 0 && !checkedProcesses.includes(r.工程区分)) return false;

      // 作業者絞り込み
      if (workerSelect && r.作業者ID !== workerSelect) return false;

      return true;
    });

    renderRows(filtered);
  });

  // 4. クリアボタンのイベントリスナー
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#line-select").value = '';
    container.querySelector("#product-search").value = '';
    container.querySelector("#start-date").value = '';
    container.querySelector("#end-date").value = '';
    container.querySelector("#worker-select").value = '';
    container.querySelectorAll('input[type="checkbox"]').forEach(cb => cb.checked = false);

    // 全件再表示
    window.aivicApi.list(5).then(rows => {
      if (rows) renderRows(rows);
    });
  });

  // 5. CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(5);
    if (!rows || rows.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['生産指示書番号', '製品名', '工程名', 'ライン名', '作業者名', '実績数量', '良品数量', '作業状況', '作業開始日時', '作業終了日時'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...rows.map(r => [
        r.生産指示書番号 || '',
        r.製品名 || '',
        r.工程名 || '',
        r.ライン名 || '',
        r.作業者名 || '',
        r.実績数量 || 0,
        r.良品数量 || 0,
        r.作業状況 || '',
        r.作業開始日時 || '',
        r.作業終了日時 || ''
      ].map(field => `"${field}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `作業実績_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 6. 行クリック・詳細ボタンのイベントデリゲーション
  container.addEventListener("click", async (e) => {
    const row = e.target.closest(".work-row");
    const detailBtn = e.target.closest(".detail-btn");

    if (detailBtn || row) {
      const rowId = (detailBtn?.dataset.id) || row?.dataset.id;
      if (!rowId) return;

      selectedRowId = rowId;

      // 選択行のハイライト
      container.querySelectorAll(".work-row").forEach(r => {
        r.style.background = r.dataset.id === rowId ? 'rgba(59, 130, 246, 0.1)' : '';
      });

      // 作業実績詳細を取得して表示
      const rows = await window.aivicApi.list(5);
      const workResult = rows?.find(r => r.作業実績ID === rowId);
      updateDetailPanel(workResult);

      // 品質検査結果を更新
      await updateQualityPanel(rowId);
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#plan-tbody");
  let allPlans = [];
  let selectedPlanId = null;

  // 進捗率計算関数
  function calculateProgress(planned, actual) {
    if (!planned || planned === 0) return 0;
    return Math.min(Math.round((actual / planned) * 100), 100);
  }

  // ステータス表示用のバッジ生成
  function getStatusBadge(status) {
    const colors = {
      '未着手': 'background: rgba(128,128,128,0.2); color: var(--text);',
      '進行中': 'background: rgba(59,130,246,0.2); color: #3b82f6;',
      '完了': 'background: rgba(34,197,94,0.2); color: #22c55e;',
      '中断': 'background: rgba(239,68,68,0.2); color: #ef4444;',
      '遅延': 'background: rgba(245,158,11,0.2); color: #f59e0b;'
    };
    const style = colors[status] || 'background: rgba(128,128,128,0.2); color: var(--text);';
    return `<span style="padding: 0.25rem 0.5rem; border-radius: 12px; font-size: 0.75rem; ${style}">${status}</span>`;
  }

  // 品質検査結果アイコン生成
  function getQualityIcon(goodQty, defectQty) {
    const total = (goodQty || 0) + (defectQty || 0);
    if (total === 0) return '<span style="color: var(--text-muted);">-</span>';

    const defectRate = (defectQty / total) * 100;
    if (defectRate === 0) {
      return '<span style="color: #22c55e;">✓</span>';
    } else if (defectRate < 5) {
      return '<span style="color: #f59e0b;">⚠</span>';
    } else {
      return '<span style="color: #ef4444;">✗</span>';
    }
  }

  // 日時フォーマット関数
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP') + ' ' + date.toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'});
  }

  // テーブル再描画関数
  function renderRows(plans) {
    tbody.innerHTML = plans.map(plan => {
      const progress = calculateProgress(plan.生産予定数量, plan.生産実績数量);
      return `
        <tr data-id="${plan.生産指示書ID}" style="cursor: pointer;" class="plan-row">
          <td>${plan.生産指示書番号 || '-'}</td>
          <td>${plan.製品名 || '-'}</td>
          <td>${plan.ライン名 || '-'}</td>
          <td style="text-align: right;">${plan.生産予定数量 || 0}</td>
          <td style="text-align: right;">${plan.生産実績数量 || 0}</td>
          <td style="text-align: right;">${progress}%</td>
          <td>${getStatusBadge(plan.ステータス || '未着手')}</td>
          <td>${formatDateTime(plan.生産開始予定日時)}</td>
          <td>${formatDateTime(plan.生産完了予定日時)}</td>
          <td style="text-align: center;">${getQualityIcon(plan.良品数量, plan.不良品数量)}</td>
          <td>
            <button class="action-btn secondary work-result-btn" data-id="${plan.生産指示書ID}" style="font-size: 0.75rem; padding: 0.25rem 0.5rem;">
              作業実績
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 詳細パネル更新関数
  function updateDetailPanel(plan) {
    if (!plan) {
      container.querySelector("#detail-number").textContent = '-';
      container.querySelector("#detail-product").textContent = '-';
      container.querySelector("#detail-line").textContent = '-';
      container.querySelector("#detail-priority").textContent = '-';
      container.querySelector("#detail-planned-qty").textContent = '-';
      container.querySelector("#detail-actual-qty").textContent = '-';
      container.querySelector("#detail-good-qty").textContent = '-';
      container.querySelector("#detail-defect-qty").textContent = '-';
      container.querySelector("#detail-remarks").textContent = '-';
      return;
    }

    container.querySelector("#detail-number").textContent = plan.生産指示書番号 || '-';
    container.querySelector("#detail-product").textContent = plan.製品名 || '-';
    container.querySelector("#detail-line").textContent = plan.ライン名 || '-';
    container.querySelector("#detail-priority").textContent = plan.優先度 || '-';
    container.querySelector("#detail-planned-qty").textContent = plan.生産予定数量 || '-';
    container.querySelector("#detail-actual-qty").textContent = plan.生産実績数量 || '-';
    container.querySelector("#detail-good-qty").textContent = plan.良品数量 || '-';
    container.querySelector("#detail-defect-qty").textContent = plan.不良品数量 || '-';
    container.querySelector("#detail-remarks").textContent = plan.備考 || '-';
  }

  // フィルタ関数
  function filterPlans() {
    const productName = container.querySelector("#search-product").value.toLowerCase();
    const lineName = container.querySelector("#search-line").value;
    const startDate = container.querySelector("#search-start-date").value;
    const endDate = container.querySelector("#search-end-date").value;
    const status = container.querySelector("#search-status").value;

    const filtered = allPlans.filter(plan => {
      // 製品名フィルタ
      if (productName && !(plan.製品名 || '').toLowerCase().includes(productName)) {
        return false;
      }

      // ラインフィルタ
      if (lineName && plan.ライン名 !== lineName) {
        return false;
      }

      // 開始日フィルタ
      if (startDate && plan.生産開始予定日時) {
        const planDate = new Date(plan.生産開始予定日時).toISOString().split('T')[0];
        if (planDate < startDate) return false;
      }

      // 終了日フィルタ
      if (endDate && plan.生産完了予定日時) {
        const planDate = new Date(plan.生産完了予定日時).toISOString().split('T')[0];
        if (planDate > endDate) return false;
      }

      // ステータスフィルタ
      if (status && plan.ステータス !== status) {
        return false;
      }

      return true;
    });

    renderRows(filtered);
  }

  // CSVエクスポート関数
  function exportCSV() {
    const headers = ['生産指示書番号', '製品名', '製造ライン', '予定数量', '実績数量', '進捗率', 'ステータス', '開始予定', '完了予定'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
      allPlans.map(plan => {
        const progress = calculateProgress(plan.生産予定数量, plan.生産実績数量);
        return [
          plan.生産指示書番号 || '',
          plan.製品名 || '',
          plan.ライン名 || '',
          plan.生産予定数量 || 0,
          plan.生産実績数量 || 0,
          progress + '%',
          plan.ステータス || '',
          formatDateTime(plan.生産開始予定日時),
          formatDateTime(plan.生産完了予定日時)
        ].map(field => `"${field}"`).join(',');
      }).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '生産計画一覧_' + new Date().toISOString().split('T')[0] + '.csv';
    link.click();
  }

  // 初期データ読み込み
  window.aivicApi.list(4).then(plans => {
    if (plans) {
      allPlans = plans;
      renderRows(plans);
    }
  });

  // 検索ボタンイベント
  container.querySelector("#btn-search").addEventListener("click", filterPlans);

  // クリアボタンイベント
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#search-product").value = '';
    container.querySelector("#search-line").value = '';
    container.querySelector("#search-start-date").value = '';
    container.querySelector("#search-end-date").value = '';
    container.querySelector("#search-status").value = '';
    renderRows(allPlans);
  });

  // CSVエクスポートボタンイベント
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 画面遷移ボタンイベント
  container.querySelector("#btn-forecast").addEventListener("click", () => {
    window.showScreen("scr-1780995149463");
  });

  container.querySelector("#btn-instruction").addEventListener("click", () => {
    window.showScreen("scr-1780995137049");
  });

  // 行クリックイベント（詳細表示）
  container.addEventListener("click", (e) => {
    const row = e.target.closest(".plan-row");
    if (row && !e.target.closest("button")) {
      const planId = row.dataset.id;
      selectedPlanId = planId;

      // 選択行のハイライト
      container.querySelectorAll(".plan-row").forEach(r => r.style.backgroundColor = '');
      row.style.backgroundColor = 'rgba(59,130,246,0.1)';

      // 詳細パネル更新
      const plan = allPlans.find(p => p.生産指示書ID === planId);
      updateDetailPanel(plan);
    }

    // 作業実績ボタンクリック
    const workBtn = e.target.closest(".work-result-btn");
    if (workBtn) {
      e.stopPropagation();
      const planId = workBtn.dataset.id;
      // 作業実績画面への遷移（実装時に適切な画面IDに変更）
      console.log('作業実績参照:', planId);
    }
  });
}

function(container, apiUrl, tables) {
  // サンプル予測データ
  const sampleForecastData = [
    { id: '1', productName: 'エンジン部品A', category: '部品', lastMonth: 1250, lastYear: 1180, forecast: 1320, accuracy: 89.2, trend: '+5.6%' },
    { id: '2', productName: '制御基板B', category: '半製品', lastMonth: 850, lastYear: 920, forecast: 780, accuracy: 92.1, trend: '-8.1%' },
    { id: '3', productName: '完成品C', category: '完成品', lastMonth: 450, lastYear: 380, forecast: 520, accuracy: 85.7, trend: '+15.6%' },
    { id: '4', productName: 'センサー部品D', category: '部品', lastMonth: 2100, lastYear: 1950, forecast: 2250, accuracy: 91.3, trend: '+7.1%' },
    { id: '5', productName: 'モーター組立E', category: '半製品', lastMonth: 680, lastYear: 720, forecast: 650, accuracy: 88.9, trend: '-4.4%' }
  ];

  let currentData = [...sampleForecastData];

  // 再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector('#forecast-tbody');
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.productName || ''}</td>
        <td>${r.category || ''}</td>
        <td style="text-align: right;">${r.lastMonth?.toLocaleString() || ''}</td>
        <td style="text-align: right;">${r.lastYear?.toLocaleString() || ''}</td>
        <td style="text-align: right; font-weight: 600; color: var(--primary);">${r.forecast?.toLocaleString() || ''}</td>
        <td style="text-align: right;">${r.accuracy || ''}%</td>
        <td style="text-align: right; color: ${r.trend?.startsWith('+') ? '#22c55e' : '#ef4444'};">${r.trend || ''}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.id}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // 初期データ描画
  renderRows(currentData);

  // グラフ描画関数
  function drawForecastChart() {
    const canvas = container.querySelector('#forecast-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスサイズ調整
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * 2;
    canvas.height = rect.height * 2;
    ctx.scale(2, 2);

    const width = rect.width;
    const height = rect.height;

    ctx.clearRect(0, 0, width, height);

    // 実績データ（過去6ヶ月）
    const actualData = [1200, 1150, 1300, 1250, 1180, 1250];
    const forecastData = [1320, 1380, 1420, 1350, 1400, 1450];
    const months = ['7月', '8月', '9月', '10月', '11月', '12月'];

    const padding = 40;
    const chartWidth = width - padding * 2;
    const chartHeight = height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // 実績線描画
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (i / (actualData.length - 1)) * chartWidth;
      const y = height - padding - ((actualData[i] - 1000) / 500) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測線描画
    ctx.strokeStyle = '#f59e0b';
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    for (let i = 0; i < forecastData.length; i++) {
      const x = padding + (i / (forecastData.length - 1)) * chartWidth;
      const y = height - padding - ((forecastData[i] - 1000) / 500) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.setLineDash([]);

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('実績', padding, 20);
    ctx.fillText('予測', padding + 60, 20);
  }

  function drawTrendChart() {
    const canvas = container.querySelector('#trend-chart');
    const ctx = canvas.getContext('2d');

    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * 2;
    canvas.height = rect.height * 2;
    ctx.scale(2, 2);

    const width = rect.width;
    const height = rect.height;

    ctx.clearRect(0, 0, width, height);

    const trendData = [2.1, 3.5, -1.2, 4.8, 2.3, 5.6];
    const padding = 30;
    const chartWidth = width - padding * 2;
    const chartHeight = height - padding * 2;

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, height / 2);
    ctx.lineTo(width - padding, height / 2);
    ctx.stroke();

    // バー描画
    const barWidth = chartWidth / trendData.length * 0.6;
    for (let i = 0; i < trendData.length; i++) {
      const x = padding + (i / trendData.length) * chartWidth + chartWidth / trendData.length * 0.2;
      const barHeight = Math.abs(trendData[i]) * 10;
      const y = trendData[i] >= 0 ? height / 2 - barHeight : height / 2;

      ctx.fillStyle = trendData[i] >= 0 ? '#22c55e' : '#ef4444';
      ctx.fillRect(x, y, barWidth, barHeight);
    }
  }

  function drawSeasonalChart() {
    const canvas = container.querySelector('#seasonal-chart');
    const ctx = canvas.getContext('2d');

    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * 2;
    canvas.height = rect.height * 2;
    ctx.scale(2, 2);

    const width = rect.width;
    const height = rect.height;

    ctx.clearRect(0, 0, width, height);

    const seasonalData = [0.85, 0.92, 1.15, 1.08, 0.95, 1.12, 1.25, 0.88, 0.98, 1.05, 1.18, 1.35];
    const padding = 20;
    const chartWidth = width - padding * 2;
    const chartHeight = height - padding * 2;

    // 基準線
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, height / 2);
    ctx.lineTo(width - padding, height / 2);
    ctx.stroke();

    // 季節性曲線
    ctx.strokeStyle = '#8b5cf6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < seasonalData.length; i++) {
      const x = padding + (i / (seasonalData.length - 1)) * chartWidth;
      const y = height - padding - ((seasonalData[i] - 0.5) / 1) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }

  // 初期グラフ描画
  setTimeout(() => {
    drawForecastChart();
    drawTrendChart();
    drawSeasonalChart();
  }, 100);

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', () => {
    const keyword = container.querySelector('#search-input').value.toLowerCase();
    const filtered = currentData.filter(row => 
      row.productName.toLowerCase().includes(keyword) ||
      row.category.toLowerCase().includes(keyword)
    );
    renderRows(filtered);
  });

  // 分析実行
  container.querySelector('#btn-analyze').addEventListener('click', async () => {
    const period = container.querySelector('#forecast-period').value;
    const category = container.querySelector('#product-category').value;
    const model = container.querySelector('#forecast-model').value;

    if (!period || !model) {
      alert('予測期間と予測モデルを選択してください');
      return;
    }

    // 分析実行のシミュレーション
    container.querySelector('#accuracy-value').textContent = (85 + Math.random() * 10).toFixed(1) + '%';
    container.querySelector('#trend-value').textContent = (Math.random() > 0.5 ? '↗ +' : '↘ -') + (Math.random() * 20).toFixed(1) + '%';

    // グラフ再描画
    drawForecastChart();
    drawTrendChart();
    drawSeasonalChart();
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', () => {
    const headers = ['製品名', '製品分類', '前月実績', '前年同月', '予測値', '予測精度', 'トレンド'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
      currentData.map(row => [
        row.productName,
        row.category,
        row.lastMonth,
        row.lastYear,
        row.forecast,
        row.accuracy + '%',
        row.trend
      ].join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = '需要予測分析_' + new Date().toISOString().slice(0, 10) + '.csv';
    a.click();
    URL.revokeObjectURL(url);
  });

  // アラート設定モーダル
  container.querySelector('#btn-alert-setting').addEventListener('click', () => {
    container.querySelector('#alert-modal').style.display = 'block';
  });

  container.querySelector('#btn-cancel-alert').addEventListener('click', () => {
    container.querySelector('#alert-modal').style.display = 'none';
  });

  container.querySelector('#btn-save-alert').addEventListener('click', async () => {
    const accuracyThreshold = container.querySelector('#accuracy-threshold').value;
    const demandThreshold = container.querySelector('#demand-threshold').value;

    // アラート設定保存のシミュレーション
    if (window.aivicApi) {
      await window.aivicApi.save(13, {
        アラート種別: '予測精度低下',
        重要度: '中',
        タイトル: '予測精度アラート設定',
        メッセージ内容: `予測精度が${accuracyThreshold}%を下回った場合に通知`,
        通知対象ユーザーID: 'current-user',
        通知ステータス: '設定済み',
        既読フラグ: false,
        対応完了フラグ: false,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString(),
        作成者ID: 'current-user'
      });
    }

    container.querySelector('#alert-modal').style.display = 'none';
    alert('アラート設定を保存しました');
  });

  // データ更新
  container.querySelector('#btn-update-data').addEventListener('click', async () => {
    if (window.aivicApi) {
      const updatedData = await window.aivicApi.list(0);
      if (updatedData) {
        currentData = updatedData;
        renderRows(currentData);
      }
    }

    // KPI更新
    container.querySelector('#accuracy-value').textContent = (85 + Math.random() * 10).toFixed(1) + '%';
    container.querySelector('#trend-value').textContent = (Math.random() > 0.5 ? '↗ +' : '↘ -') + (Math.random() * 20).toFixed(1) + '%';

    drawForecastChart();
    drawTrendChart();
    drawSeasonalChart();
  });

  // 行クリックイベント
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const row = currentData.find(r => r.id === id);
      if (row) {
        alert(`${row.productName}の詳細分析\n予測値: ${row.forecast}\n精度: ${row.accuracy}%\nトレンド: ${row.trend}`);
      }
    }
  });
}
